function offlineVideoDb(){if(!('indexedDB' in window))return Promise.reject(new Error('Este dispositivo no permite guardar videos sin conexión.'));if(!offlineVideoDbPromise)offlineVideoDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('aulaya-offline-videos-v1',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('videos'))request.result.createObjectStore('videos',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return offlineVideoDbPromise}
async function storeOfflineVideo(id,blob){const db=await offlineVideoDb();return new Promise((resolve,reject)=>{const tx=db.transaction('videos','readwrite');tx.objectStore('videos').put({id,blob,savedAt:Date.now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
