function teacherClassIcon(item,colorClass=''){const grade=String(item?.grade||'').trim(),src=GRADE_ICON_FILES[grade];if(src)colorClass=GRADE_ICON_COLORS[grade]||colorClass;return src?`<span class="teacher-class-icon grade-icon ${grade===SPECIAL_GROUP?'wide':''} ${colorClass}"><img src="${src}" alt="${escapeHtml(grade)}"></span>`:`<span class="teacher-class-icon ${colorClass}">▣</span>`}
async function deleteTeacherClass(classId){const item=(state.teacherClasses||[]).find(entry=>entry.id===classId);if(!item){state.modal=null;render();return}const button=document.querySelector('[data-teacher-action="confirm-delete-class"]');const cloud=window.aulayaDb?.isConfigured()&&window.aulayaDb.userId();if(cloud&&!navigator.onLine){toastMsg('Necesitas internet para eliminar la clase.');return}if(button){button.disabled=true;button.textContent='Eliminando…'}try{if(cloud)await window.aulayaDb.deleteTeacherClass(classId);state.teacherClasses=(state.teacherClasses||[]).filter(entry=>entry.id!==classId);if(state.teacherClassId===classId)state.teacherClassId=null;state.modal=null;state.teacherView='classes';saveState();if(cloud)await window.aulayaDb.saveProfile(cloudProfilePayload()).catch(()=>{});render();toastMsg(`${item.grade} ${item.sectionLabel} se eliminó.`)}catch(error){if(button){button.disabled=false;button.textContent='Eliminar clase'}toastMsg(error.message||'No se pudo eliminar la clase. Inténtalo de nuevo.')}}
