function lessonGameMarkup(){const g=window.AulaGames?.get(state.grade||'Primero',state.subject||'Matemáticas');if(!g)return '';const best=(state.gameStars||{})[lessonGameKey()]||0;return `<section class="lesson-game-card"><div class="lesson-game-icon"><img src="assets/game-icon.png" alt="Juego"></div><div class="lesson-game-copy"><small>Juego del tema · ${escapeHtml(g.kind)}</small><b>${escapeHtml(g.title)}</b><span>${best?'⭐'.repeat(best)+'<i>☆</i>'.repeat(3-best)+' Tu mejor resultado':'Juega y gana hasta 3 estrellas · +10 monedas la primera vez'}</span></div><button class="lesson-game-play" data-action="open-game">Jugar ▶</button></section>`}
function gamePage(){const g=window.AulaGames?.get(state.grade||'Primero',state.subject||'Matemáticas');if(!g){state.page='topic';topic();return}shell(`${heading(escapeHtml(g.title),state.gameBack||'topic')}<section class="lesson-game-stage"><div id="game-root"></div></section>`);const root=document.querySelector('#game-root');if(currentGame)currentGame.destroy();currentGame=window.AulaGames.mount(root,g,{onWin:({stars})=>{const key=lessonGameKey();state.gameStars??={};state.gamesWon??=[];const first=!state.gamesWon.includes(key);if(first){state.gamesWon.push(key);state.coins=(state.coins||0)+10}if(stars>(state.gameStars[key]||0))state.gameStars[key]=stars;saveState();const coin=document.querySelector('.coin-pill');if(coin&&first)coin.lastChild.textContent=state.coins;toastMsg(first?'¡Ganaste el juego! +10 monedas 🪙':'¡Muy bien! Las monedas del juego solo se ganan la primera vez.')},onExit:()=>{currentGame=null;state.page='topic';render()}})}
function studentActivities(){const grade=state.grade||'Primero';return (state.studentActivities||[]).filter(a=>!a.grade||a.grade===grade)}
async function refreshStudentActivities(){if(state.authRole!=='student'||!navigator.onLine||!window.aulayaDb?.isConfigured()||!window.aulayaDb.userId())return;try{const rows=await window.aulayaDb.loadMyClassActivities();if(!Array.isArray(rows))return;const list=[];(rows||[]).forEach(row=>(Array.isArray(row.activities)?row.activities:[]).forEach(a=>{if(a&&a.id)list.push({id:a.id,title:a.title||'Actividad',description:a.description||'',grade:a.grade||'',subject:a.subject||'',topic:a.topic||'',questions:Array.isArray(a.questions)?a.questions:[],material:a.videoMaterial&&a.videoMaterial.file_path?a.videoMaterial:null,special:Array.isArray(a.assignedTo)&&a.assignedTo.length>0,teacherName:row.teacher_name||'Tu docente',teacherAvatar:row.teacher_avatar??null,classLabel:row.class_label||'',createdAt:a.createdAt||''})}));list.sort((x,y)=>String(y.createdAt).localeCompare(String(x.createdAt)));const liveMat=new Set(list.filter(a=>a.material).map(a=>a.material.id)),staleMat=(state.offlineVideos||[]).filter(v=>!liveMat.has(v.id));if(staleMat.length){staleMat.forEach(v=>removeOfflineVideo(v.id).catch(()=>{}));state.offlineVideos=(state.offlineVideos||[]).filter(v=>liveMat.has(v.id))}const classes=rows.map(row=>({id:row.teacher_class_id,subjects:Array.isArray(row.class_subjects)?row.class_subjects:[],label:row.class_label||'Tu clase',teacherName:row.teacher_name||'Tu docente',teacherAvatar:row.teacher_avatar??null,joinedAt:row.joined_at||''}));const notified=studentClassNotices(classes,list);try{[...new Set(list.map(a=>a.subject))].forEach(subj=>window.AulaGames?.preload?.(state.grade||'Primero',subj))}catch(_){}const before=JSON.stringify([state.studentActivities||[],state.myClasses||[]]);state.studentActivities=list;state.myClasses=classes;if(notified||before!==JSON.stringify([list,classes])){saveState();if(['home','topic','teacher-activity','notifications','profile','class'].includes(state.page))render()}}catch(error){console.warn('No se pudieron cargar las actividades de tu docente:',error)}}
function studentActivityCard(a){const done=(state.teacherActivitiesDone||[]).includes(a.id);return `<button class="student-task-card ${done?'done':''}" data-open-student-activity="${escapeHtml(a.id)}"><span class="student-task-icon ${done?'is-done':''}">${subjectIcon(a.subject)}${done?'<i class="done-tick">✓</i>':''}</span><span class="student-task-copy">${a.special?'<em class="special-badge">⭐ Especial para ti</em>':''}<b>${escapeHtml(a.title)}</b><small>${escapeHtml(a.subject)} · ${escapeHtml(a.topic)}${a.questions.length?` · ${a.questions.length} ${a.questions.length===1?'pregunta':'preguntas'}`:''}</small><small class="by-teacher">${teacherFace(a.teacherAvatar,a.teacherName,'mini')} ${escapeHtml(a.teacherName)}</small></span><i>›</i></button>`}
function studentActivityMaterials(){const out=[];for(const a of studentActivities()){if(a.material&&a.material.id&&!out.some(m=>m.id===a.material.id))out.push({...a.material,teacherName:a.teacherName,teacherAvatar:a.teacherAvatar,title:a.material.title||a.title,grade:a.material.grade||a.grade,subject:a.material.subject||a.subject,topic:a.material.topic||a.topic,activityTitle:a.title})}for(const m of (state.sharedClassMaterials||[]))if(m&&m.id&&!out.some(x=>x.id===m.id)&&isTopicPublished(m.subject,m.topic))out.push(m);return out}
function fmtBytes(n){n=Number(n)||0;if(!n)return '';return n>1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(n/1024))} KB`}
function fileBadge(m){const t=String(m.mime_type||''),ext=fileExtension(m.file_path||'').toUpperCase();if(t.startsWith('video/'))return ['video-art','<img src="assets/video-material.png" alt="Video">'];if(t.startsWith('image/'))return ['img','IMG'];if(t.includes('pdf')||fileExtension(m.file_path||'')==='pdf')return ['video-art','<img src="assets/pdf-material.png" alt="PDF">'];return ['doc',ext&&ext!=='BIN'?ext.slice(0,4):'DOC']}
