function noticeIcon(n){if((n.kind==='material'||n.kind==='activity'||n.kind==='class')&&n.teacherName)return `<span class="notice-face">${teacherFace(n.teacherAvatar,n.teacherName,'big')}<i class="notice-badge">${n.kind==='material'?uiIcon('material'):n.kind==='class'?'🏫':n.title&&n.title.includes('especial')?uiIcon('special'):uiIcon('activity')}</i></span>`;if(n.kind==='material')return '<img src="assets/Descargaslogosam.png" alt="">';if(n.kind==='class')return '<img src="assets/mis-clases.png" alt="">';if(n.kind==='activity')return n.title&&n.title.includes('especial')?uiIcon('special','notice-svg'):uiIcon('activity','notice-svg');if(n.id==='gift')return '<img src="assets/mondeaconlogo.png" alt="">';return '<img src="assets/aulaya-mascot.png" alt="">'}
function timeAgo(iso){const t=Date.parse(iso||'');if(!t)return '';const m=Math.round((Date.now()-t)/60000);if(m<1)return 'Ahora';if(m<60)return `Hace ${m} min`;const h=Math.round(m/60);if(h<24)return `Hace ${h} h`;const d=Math.round(h/24);return d===1?'Ayer':`Hace ${d} días`}
