function starEarnedToday(){return state.lastStreakDate===todayKey()}
function markLessonComplete(){const key=`${state.subject}:${state.topic}`;state.lessonCompletions??=[];if(!state.lessonCompletions.includes(key))state.lessonCompletions.push(key);if(state.lastStreakDate!==todayKey()){state.streak=(state.streak||0)+1;state.lastStreakDate=todayKey();return true}return false}
