function studentLookSrc(id){const r=(state.classProgress||[]).find(x=>x.student_id===id&&x.student_look),lk=r&&r.student_look;if(!lk)return 'assets/aulaya-mascot.png';const eq=lk.equipped||{},ren=(typeof ROPA_RENOMBRE==='object'&&ROPA_RENOMBRE)||{},ow=(Array.isArray(lk.owned)?lk.owned:[]).map(n=>ren[n]||n);const n=['Ropa','Accesorios'].map(c=>eq[c]&&(ren[eq[c]]||eq[c])).find(n=>n&&ow.includes(n)&&TEO_LOOKS[n]);return n?TEO_LOOKS[n]:'assets/aulaya-mascot.png'}
