const TEO_SPOT={torso:[50,44,.26],head:[50,7,.2],eyes:[52,22.5,.2],neck:[50,34,.15],back:[80,44,.2]};
function wearOnly(cat){const other=cat==='Ropa'?'Accesorios':cat==='Accesorios'?'Ropa':null;if(!other||!state.equipped)return '';const prev=state.equipped[other];state.equipped[other]=null;return prev?` (se quitó ${prev})`:''}
function teoLook(preview){const eq=state.equipped||{},owned=state.owned||[],look={};['Ropa','Accesorios'].forEach(c=>{const n=eq[c];if(n&&owned.includes(n))look[c]=n});if(preview&&preview.cat)look[preview.cat]=preview.name;return look}
function teoDressed(h,preview){const look=teoLook(preview);const parts='';const _unused=Object.values(look).map(n=>{const w=TEO_WEAR[n];if(!w)return '';const [x,y,f]=TEO_SPOT[w[1]];return `<i class="teo-wear wear-${w[1]}" style="left:${x}%;top:${y}%;font-size:${Math.round(h*f)}px;${w[2]?`filter:${w[2]};`:''}">${w[0]}</i>`}).join('');const pick=(preview&&TEO_LOOKS[preview.name])?preview.name:Object.values(look).find(n=>TEO_LOOKS[n]);return `<span class="teo-dressed" style="height:${h}px"><img src="${pick?TEO_LOOKS[pick]:'assets/aulaya-mascot.png'}" alt="Teo, el jaguar de Aula ya!${pick?' con '+pick:''}">${parts}</span>`}

