function toastMsg(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toast._timer);toast._timer=setTimeout(()=>toast.classList.remove('show'),2300)}
function brand(){return `<div class="brand"><img src="assets/aulaya-logo-white.png" alt="Aula ya!"></div>`}
function header(){return `<header class="app-header"><div data-go="home">${brand()}</div><div class="head-actions"><button class="head-button streak-button" data-go="profile" aria-label="Racha de ${state.streak} ${state.streak===1?'día':'días'}${starEarnedToday()?', estrella de hoy ganada':''}"><span class="streak-star ${starEarnedToday()?'earned':''}">★</span><span style="font-size:10px;font-weight:900">${state.streak}</span></button><button class="head-button" data-go="notifications" aria-label="Notificaciones"><img class="notification-logo" src="assets/notification-icon.png" alt="">${state.noticeRead?'':'<i class="notif-dot"></i>'}</button><button class="coin-pill" data-go="custom"><img class="coin-icon" src="assets/mondeaconlogo.png" alt="Monedas">${state.coins}</button></div></header>`}
function nav(){let links=[['home','inicio','⌂','Inicio'],['downloads','descargas','♧','Descargas'],['assistant','teo-ia','✦','Teo'],['custom','personalizacion','◉','Personalización'],['profile','perfil','♙','Perfil']];return `<nav class="bottom-nav">${links.map(([id,key,ico,label])=>`<button class="nav-button ${state.page===id?'active':''}" data-go="${id}"><span class="nav-glyph">${id==='home'?'<img class="nav-home-logo" src="assets/inicio-casa.png" alt="">':id==='downloads'?'<img class="nav-download-logo" src="assets/Descargaslogosam.png" alt="">':id==='assistant'?'<img class="nav-ai-logo" src="assets/LogoSML.png" alt="">':id==='custom'?'<img class="nav-personal-logo" src="assets/personalizcionsam.png" alt="">':id==='profile'?'<img class="nav-profile-logo" src="assets/PERFILSAM.png" alt="">':ico}</span>${label}${id==='downloads'&&state.pending.length?`<i class="nav-count" aria-label="${state.pending.length} materiales pendientes">${state.pending.length}</i>`:''}</button>`).join('')}</nav>`}
function subjectLogo(){return ({'Matemáticas':'Matematicasoriginal.png','Lengua':'Lenguanuevo.png','Ciencias':'Ciencias.png','Inglés':'inglessam.png','Ciencias Sociales':'socialessam.png'})[state.subject]||'Matematicasoriginal.png'}
function shell(content){app.innerHTML=state.page==="auth"?`<section class="auth-shell">${content}</section>`:header()+`<section class="page">${content}</section>`+nav();if(['class','topic'].includes(state.page)&&state.subject==='Matemáticas')document.querySelectorAll('.teacher-mascot').forEach(el=>{el.className='subj-badge s-'+subjectKey('Matemáticas');el.innerHTML=subjectIcon('Matemáticas')});if(['class','topic'].includes(state.page)&&state.subject==='Lengua')document.querySelectorAll('.teacher-mascot').forEach(el=>{el.className='subj-badge s-'+subjectKey('Lengua');el.innerHTML=subjectIcon('Lengua')});if(['class','topic'].includes(state.page)&&state.subject==='Ciencias')document.querySelectorAll('.teacher-mascot').forEach(el=>{el.className='subj-badge s-'+subjectKey('Ciencias');el.innerHTML=subjectIcon('Ciencias')});if(['class','topic'].includes(state.page)&&state.subject==='Inglés')document.querySelectorAll('.teacher-mascot').forEach(el=>{el.className='subj-badge s-'+subjectKey('Inglés');el.innerHTML=subjectIcon('Inglés')});if(['class','topic'].includes(state.page)&&state.subject==='Ciencias Sociales')document.querySelectorAll('.teacher-mascot').forEach(el=>{el.className='subj-badge s-'+subjectKey('Ciencias Sociales');el.innerHTML=subjectIcon('Ciencias Sociales')})}
function home(){const active=state.inProgressActivities.filter(item=>!state.completedActivities.includes(`${item.subject}:${item.topic}:${item.name}`));shell(`<section class="hero"><div class="hero-topline"><div class="hero-greet">¡Hola, ${String(state.firstName||state.profile||"").trim().split(/\s+/)[0]||"estudiante"}! ✨<small>¿Qué quieres aprender hoy?</small></div></div><div class="hero-cloud">☁</div><div class="mascot">${avatarMarkup()}</div></section>
  ${state.offline?`<div class="offline-banner"><span class="offline-icon">◉</span><div><b>Estás sin internet 📴</b><small>¡Sigue aprendiendo! Todo lo que hagas se guarda aquí y se sube solito cuando vuelva el internet.</small></div><button data-action="dismiss-offline">✕</button></div>`:''}
  ${myClassesMarkup()}${studentSubjectGrid()}${studentHomeActivities()}
  ${state.offline?`<div class="section-title"><h2>Contenido descargado</h2><button data-go="downloads">Ver todo →</button></div><div class="course-row" data-go="downloads"><span class="course-icon svg-ico">${uiIcon('material')}</span><span class="course-detail"><b>Tus materiales disponibles</b><small>Aquí tienes tus actividades y guías</small></span><span class="chevron">›</span></div>`:''}
  <div class="section-title"><h2>Actividades en progreso</h2></div>${active.length?active.map((item,index)=>`<div class="course-row progress-activity" data-resume-activity="${index}"><span class="course-icon svg-ico">${subjectIcon(item.subject)}</span><span class="course-detail"><b>${item.name}</b><small>${item.subject} · ${item.topic}</small><span class="progress-line"><i style="width:${item.progress||0}%"></i></span></span><span class="course-pct">${item.progress||0}%</span><span class="chevron">›</span></div>`).join(''):`<div class="empty-state activity-empty"><img class="empty-progress-books" src="assets/librosnoprogreso.png" alt="Libros esperando a que empieces una actividad"><b>Aún no hay actividades en progreso</b><p>Cuando empieces una actividad, aparecerá aquí.</p></div>`}
`)}
