function lessonVideoMarkup(){const video=lessonVideos[state.grade||'Primero']?.[state.subject];if(!video)return '';if(!navigator.onLine)return `<section class="lesson-video-card video-offline"><h2>Video recomendado</h2><div class="video-offline-box"><span>📶</span><div><b>Este video necesita internet</b><small>Mientras tanto puedes jugar y responder las preguntas. Cuando vuelva el internet, aquí podrás verlo.</small></div></div></section>`;const match=video.url.match(/[?&]v=([^&]+)/),creator=video.creator||'Autoría indicada por el canal de origen';return `<section class="lesson-video-card"><h2>Video recomendado</h2><p>${escapeHtml(video.title)}</p>${match?`<div class="lesson-video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(match[1])}" title="${escapeHtml(video.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>`:`<div class="lesson-video-search"><span>▶</span><b>${video.external?'Video alojado en Mediateca EducaMadrid':'Elige un video educativo para esta lección'}</b><a href="${video.url}" target="_blank" rel="noopener noreferrer">${video.external?'Abrir video':'Ver opciones en YouTube'} ↗</a></div>`}<div class="video-attribution"><b>Créditos y derechos</b><span>Autor/canal: ${escapeHtml(creator)}${video.creator?'':' (verifica el creador al abrir el video)'}</span><small>El video y sus derechos pertenecen a su autor o canal. Aula Ya enlaza el contenido como recurso educativo.</small><a href="${video.url}" target="_blank" rel="noopener noreferrer">Abrir fuente original ↗</a></div></section>`}
function teacherActivityTopics(classId=''){const classItem=(state.teacherClasses||[]).find(item=>item.id===classId),grades=classItem?(classItem.grade===SPECIAL_GROUP?[...ALL_GRADES]:[classItem.grade]):teacherClassOptions(),registered=state.variedSubjects?['Ciencias','Matemáticas','Lengua','Inglés','Ciencias Sociales']:(state.teacherSubjects||[]),classSubjects=classItem?.subjects?.length?classItem.subjects:registered,subjects=registered.filter(subject=>classSubjects.includes(subject));return grades.flatMap(grade=>subjects.flatMap(subject=>lessonCatalog[grade]?.[subject]?[{grade,subject,topic:lessonCatalog[grade][subject]}]:[]))}
function teacherClasses(){const classes=state.teacherClasses||[],classCards=classes.map((item,index)=>`<button class="teacher-class-card" data-teacher-action="open-class" data-class-id="${escapeHtml(item.id)}">${teacherClassIcon(item,`color-${index%5}`)}<span class="teacher-class-copy"><b>${escapeHtml(item.grade)} ${escapeHtml(item.sectionLabel)}</b><span class="class-subject-row">${(item.subjects||[]).length?subjectChips(item.subjects):'<span class="subject-chip sc-none">Sin materias</span>'}</span><small>${(item.students||[]).length} ${(item.students||[]).length===1?'estudiante':'estudiantes'}</small></span><span class="teacher-card-arrow">›</span></button>`).join('');app.innerHTML=`${teacherHeader('home')}<main class="teacher-page teacher-classes-page"><div class="teacher-screen-title"><div><h1>Mis clases</h1><p>Organiza tus grados, secciones y estudiantes.</p></div><span class="teacher-count-pill">${classes.length} ${classes.length===1?'clase':'clases'}</span></div><button class="teacher-create-class" data-teacher-action="add-class">＋ &nbsp; Crear clase</button>${classes.length?`<section class="teacher-class-list">${classCards}</section>`:`<section class="teacher-empty-classes"><span><img src="assets/clases-libro.png" alt=""></span><h2>Aún no tienes clases disponibles</h2><p>Crea tu primera clase. Podrás indicar el grado, la sección y agregar estudiantes.</p><button class="wide-button" data-teacher-action="add-class">＋ Crear mi primera clase</button></section>`}</main>${teacherNav('classes')}`}
function teacherNav(active='home'){return `<nav class="teacher-nav"><button class="${active==='home'?'active':''}" data-teacher-action="home"><span><img class="teacher-nav-home-logo" src="assets/inicio-casa.png" alt=""></span>Inicio</button><button class="${active==='classes'?'active':''}" data-teacher-action="classes"><span><img class="teacher-nav-home-logo" src="assets/clases-libro.png" alt=""></span>Clases</button><button class="${active==='reports'?'active':''}" data-teacher-action="reports"><span><img class="teacher-nav-home-logo" src="assets/reportes-barras.png" alt=""></span>Reportes</button><button class="${active==='profile'?'active':''}" data-teacher-action="profile"><span><img class="teacher-nav-home-logo" src="assets/perfil-docente.png" alt=""></span>Perfil</button></nav>`}
function teacherClassDetail(){const item=(state.teacherClasses||[]).find(entry=>entry.id===state.teacherClassId);if(!item){state.teacherView='classes';teacherClasses();return}refreshClassProgress();const info=classProgressInfo(item),students=info.students,activities=item.activities||[],rows=students.map((student,index)=>`<div class="teacher-student-row rp-clickable" data-teacher-action="open-student-report" data-class-id="${escapeHtml(item.id)}" data-student-id="${escapeHtml(student.id)}"><span class="teacher-student-avatar stu-photo">${studentFace(student.id)}</span><div class="tsr-copy"><b>${escapeHtml(student.name||'Estudiante')}</b><small>${student.total?`${student.doneCount} de ${student.total} ${student.total===1?'actividad hecha':'actividades hechas'}${student.pct!==null?` · promedio de aciertos`:''}`:'Sin actividades publicadas'}</small>${student.total?progressBar(student.pct):''}</div><span class="tsr-pct">${pctLabel(student.pct)}</span></div>`).join(''),activityRows=activities.map(activity=>`<div class="teacher-activity-row"><span class="tar-icon">${subjectIcon(activity.subject)}</span><div class="tar-copy"><b>${escapeHtml(activity.title)}</b><small>${escapeHtml([activity.grade,activity.subject==='Lengua'?'Lenguaje':activity.subject==='Ciencias Sociales'?'Sociales':activity.subject,activity.topic].filter(Boolean).join(' · ')||activity.description||'Actividad de clase')}</small>${(activity.assignedTo||[]).length?`<small class="tar-special">⭐ Solo para: ${escapeHtml((activity.assignedNames||[]).join(', ')||`${activity.assignedTo.length} estudiante(s)`)}</small>`:''}${activity.videoMaterial?`<small class="tar-file">📎 ${escapeHtml(activity.videoMaterial.title||'Archivo')}${activity.videoMaterial.file_size?` · ${fmtBytes(activity.videoMaterial.file_size)}`:''}</small>`:''}</div><button class="tar-remove" data-teacher-action="remove-activity" data-class-id="${escapeHtml(item.id)}" data-activity-id="${escapeHtml(activity.id)}">Quitar</button></div>`).join('');app.innerHTML=`${teacherHeader('classes')}<main class="teacher-page teacher-classes-page"><div class="teacher-screen-title"><div><h1>${escapeHtml(item.grade)} ${escapeHtml(item.sectionLabel)}</h1><p>${item.grade===SPECIAL_GROUP?`Grupo especial · De primero a quinto · ${item.sectionType==='letter'?'Sección':'Grupo'} ${escapeHtml(item.sectionLabel)}`:`${item.sectionType==='letter'?'Sección':'Grupo'} ${escapeHtml(item.sectionLabel)} · ${escapeHtml(item.grade)}`}</p></div></div><section class="teacher-class-overview">${teacherClassIcon(item,'color-2')}<div><b>${students.length} ${students.length===1?'estudiante':'estudiantes'} · ${activities.length} ${activities.length===1?'actividad':'actividades'}</b><small class="course-progress-line">Promedio del curso: <b>${pctLabel(info.coursePct)}</b>${info.coursePct!==null?progressBar(info.coursePct):''}</small><div class="class-subject-row">${(item.subjects||[]).length?subjectChips(item.subjects):'<span class="subject-chip sc-none">Sin materias</span>'}<button class="subject-edit" data-teacher-action="edit-class-subjects" data-class-id="${escapeHtml(item.id)}">${(item.subjects||[]).length?'Editar':'＋ Elegir materias'}</button></div></div></section><button class="teacher-create-class" data-teacher-action="add-student" data-class-id="${escapeHtml(item.id)}">＋ &nbsp; Agregar estudiante</button><div class="teacher-section-title"><h2>Estudiantes</h2><span class="teacher-count-pill">${students.length}</span></div>${students.length?`<section class="teacher-student-list">${rows}</section>`:`<section class="teacher-empty-classes teacher-empty-students"><h2>Aún no hay estudiantes</h2><p>Agrega estudiantes para organizar el grupo y seguir su aprendizaje.</p><button class="wide-button" data-teacher-action="add-student" data-class-id="${escapeHtml(item.id)}">＋ Agregar estudiante</button></section>`}<div class="teacher-section-title"><h2>Actividades</h2><button data-teacher-action="add-activity" data-class-id="${escapeHtml(item.id)}">＋ Crear</button></div>${activities.length?`<section class="teacher-activity-list">${activityRows}</section>`:`<div class="teacher-mini-empty">Todavía no hay actividades para esta clase.</div>`}<button class="teacher-delete-class" data-teacher-action="delete-class" data-class-id="${escapeHtml(item.id)}">Eliminar clase</button></main>${teacherNav('classes')}`}
function teacherStudents(){const entries=(state.teacherClasses||[]).flatMap(item=>(item.students||[]).map(student=>({...student,grade:item.grade,sectionLabel:item.sectionLabel}))),rows=entries.map((student,index)=>`<div class="teacher-student-row"><span class="teacher-student-avatar stu-photo">${studentFace(student.id)}</span><div><b>${escapeHtml(student.name)}</b><small>${escapeHtml(student.grade)} ${escapeHtml(student.sectionLabel)}</small></div></div>`).join('');app.innerHTML=`${teacherHeader('home')}<main class="teacher-page teacher-classes-page"><div class="teacher-screen-title"><div><h1>Estudiantes</h1><p>Alumnado de tus clases</p></div><span class="teacher-count-pill">${entries.length}</span></div>${entries.length?`<section class="teacher-student-list">${rows}</section>`:`<section class="teacher-empty-classes"><span><img src="assets/estudiantes.png" alt=""></span><h2>Aún no tienes estudiantes</h2><p>Crea una clase y agrega sus estudiantes para verlos aquí.</p><button class="wide-button" data-teacher-action="classes">Ir a mis clases</button></section>`}</main>${teacherNav()}`}
function studentStatus(st){if(!st.total)return {key:'none',label:'Sin actividades'};if(st.pct===null)return st.doneCount?{key:'idle',label:'En curso'}:{key:'idle',label:'Sin empezar'};if(st.pct<=60)return {key:'low',label:'Necesita apoyo'};if(st.pct<80)return {key:'mid',label:'Va bien'};return {key:'high',label:'Va muy bien'}}
function studentTrend(st){const sc=(st.timeline||[]).filter(t=>t.score!==null).map(t=>t.score);if(sc.length<2)return {key:'flat',label:sc.length?'Primera actividad':'—',icon:''};const k=Math.min(2,Math.floor(sc.length/2)),first=sc.slice(0,k).reduce((a,b)=>a+b,0)/k,last=sc.slice(-k).reduce((a,b)=>a+b,0)/k,d=Math.round(last-first);if(d>=10)return {key:'up',label:`Mejorando (+${d})`,icon:'↗'};if(d<=-10)return {key:'down',label:`Bajando (${d})`,icon:'↘'};return {key:'flat',label:'Estable',icon:'→'}}
function sparkline(st,w=96,h=30){const pts=(st.timeline||[]).filter(t=>t.score!==null);if(!pts.length)return `<svg class="spark" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><line x1="2" y1="${h/2}" x2="${w-2}" y2="${h/2}" stroke="#dfe7da" stroke-width="2" stroke-dasharray="3 4"/></svg>`;const step=pts.length>1?(w-8)/(pts.length-1):0,xy=pts.map((p,i)=>[4+(pts.length>1?i*step:(w-8)/2),h-4-(p.score/100)*(h-8)]);const col=studentStatus(st).key==='low'?'#d0574a':studentStatus(st).key==='mid'?'#d99a21':'#2f8a4f';return `<svg class="spark" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><line x1="2" y1="${h-4-0.6*(h-8)}" x2="${w-2}" y2="${h-4-0.6*(h-8)}" stroke="#f1d3cf" stroke-width="1" stroke-dasharray="2 3"/>${pts.length>1?`<polyline points="${xy.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${col}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>`:''}${xy.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.8" fill="#fff" stroke="${col}" stroke-width="2"/>`).join('')}</svg>`}
function initials(name){return String(name||'?').trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'?'}
function teacherStudentReport(){const item=(state.teacherClasses||[]).find(c=>c.id===state.reportClassId),st=item&&classProgressInfo(item).students.find(x=>x.id===state.reportStudentId);if(!st){state.teacherView='reports';teacherReports();return}refreshClassProgress();const status=studentStatus(st),trend=studentTrend(st);app.innerHTML=`${teacherHeader('reports')}<main class="teacher-page rp-page"><button class="rp-back" data-teacher-action="reports">‹ Reportes</button><section class="rp-hero"><span class="rp-avatar lg stu-photo">${studentFace(st.id)}</span><div><h1>${escapeHtml(st.name||'Estudiante')}</h1><p>${escapeHtml(item.grade)} ${escapeHtml(item.sectionLabel)}</p></div><span class="rp-status s-${status.key}">${status.label}</span></section><section class="rp-kpis"><div><small>Promedio de aciertos</small><b>${pctLabel(st.pct)}</b></div><div><small>Actividades hechas</small><b>${st.doneCount}<span>/${st.total}</span></b></div><div><small>Tendencia</small><b class="t-${trend.key}">${trend.icon||'—'}</b><em>${trend.label}</em></div></section><section class="rp-card"><div class="rp-card-head"><h2>Evolución</h2><small>Primer intento en cada actividad, en el orden en que las publicaste</small></div><div class="rp-chart">${sparkline(st,300,90)}</div></section><section class="rp-card"><div class="rp-card-head"><h2>Actividades</h2></div>${(st.timeline||[]).map((t,i)=>`<div class="rp-act"><span class="rp-act-n">${i+1}</span><span class="rp-act-ico">${subjectIcon(t.subject)}</span><div class="rp-act-copy"><b>${escapeHtml(t.title)}${t.special?' <em class="rp-tag">Especial</em>':''}</b><small>${escapeHtml(subjectShort(t.subject||''))}${t.topic?` · ${escapeHtml(t.topic)}`:''}</small>${t.score!==null?`<span class="rp-bar"><i class="${t.score<=60?'low':t.score<80?'mid':'high'}" style="width:${t.score}%"></i></span>`:''}</div><span class="rp-act-score ${t.score===null?'pending':t.score<=60?'low':t.score<80?'mid':'high'}">${t.score!==null?`${t.score}%`:t.done?'Hecha':'Pendiente'}</span></div>`).join('')||'<div class="teacher-mini-empty">Aún no hay actividades para este estudiante.</div>'}</section>${status.key==='low'||trend.key==='down'?`<button class="rp-cta" data-teacher-action="reinforce" data-class-id="${escapeHtml(item.id)}" data-student-id="${escapeHtml(st.id)}" data-reinforce-subject="${escapeHtml(((st.timeline||[]).filter(t=>t.score!==null).sort((a,b)=>a.score-b.score)[0]||{}).subject||'')}">＋ Crear actividad de refuerzo para ${escapeHtml(String(st.name||'').split(' ')[0])}</button>`:''}</main>${teacherNav('reports')}`}
function teacherReports(){refreshClassProgress();const classes=state.teacherClasses||[],filter=state.reportClassFilter&&classes.some(c=>c.id===state.reportClassFilter)?state.reportClassFilter:'all',entries=classes.filter(c=>filter==='all'||c.id===filter).flatMap(c=>classProgressInfo(c).students.map(st=>({c,st,status:studentStatus(st),trend:studentTrend(st)}))),order={low:0,mid:1,idle:2,high:3,none:4};entries.sort((a,b)=>order[a.status.key]-order[b.status.key]||(a.st.pct??101)-(b.st.pct??101));const count=k=>entries.filter(e=>e.status.key===k).length;app.innerHTML=`${teacherHeader('home')}<main class="teacher-page rp-page"><div class="teacher-screen-title"><div><h1>Progreso</h1><p>Cómo va cada estudiante, actividad por actividad</p></div></div>${classes.length>1?`<div class="rp-filters"><button class="${filter==='all'?'on':''}" data-teacher-action="report-filter" data-class-id="all">Todas</button>${classes.map(c=>`<button class="${filter===c.id?'on':''}" data-teacher-action="report-filter" data-class-id="${escapeHtml(c.id)}">${escapeHtml(c.grade)} ${escapeHtml(c.sectionLabel)}</button>`).join('')}</div>`:''}${entries.length?`<section class="rp-summary"><div class="s-low"><b>${count('low')}</b><small>Necesitan apoyo</small></div><div class="s-mid"><b>${count('mid')}</b><small>Van bien</small></div><div class="s-high"><b>${count('high')}</b><small>Van muy bien</small></div><div class="s-idle"><b>${count('idle')}</b><small>Sin empezar</small></div></section><section class="rp-list">${entries.map(({c,st,status,trend})=>`<button class="rp-row" data-teacher-action="open-student-report" data-class-id="${escapeHtml(c.id)}" data-student-id="${escapeHtml(st.id)}"><span class="rp-avatar stu-photo">${studentFace(st.id)}</span><span class="rp-main"><b>${escapeHtml(st.name||'Estudiante')}</b><small>${escapeHtml(c.grade)} ${escapeHtml(c.sectionLabel)} · ${st.doneCount}/${st.total} hechas${trend.icon?` · <span class="t-${trend.key}">${trend.icon} ${trend.label}</span>`:''}</small><span class="rp-status s-${status.key}">${status.label}</span></span><span class="rp-side"><b class="${status.key}">${pctLabel(st.pct)}</b>${sparkline(st)}</span><i class="rp-chev">›</i></button>`).join('')}</section><p class="report-note">El porcentaje es el promedio de aciertos en el primer intento de cada actividad. La línea muestra cómo ha ido cambiando, de la primera a la última actividad. Toca un estudiante para ver el detalle.</p>`:`<section class="teacher-empty-classes"><span><img src="assets/reportes.png" alt=""></span><h2>El progreso aparecerá aquí</h2><p>Cuando agregues estudiantes y publiques actividades, verás cómo va cada uno.</p><button class="wide-button" data-teacher-action="classes">Ver mis clases</button></section>`}</main>${teacherNav('reports')}`}
function teacherResources(){if(!state.bankLoading&&navigator.onLine&&window.aulayaDb?.loadQuestionBankSummary&&Date.now()-(state.bankAt||0)>15000){state.bankLoading=true;flushBankQuestions().finally(()=>window.aulayaDb.loadQuestionBankSummary().then(rows=>{if(Array.isArray(rows)){state.bankSummary=rows;state.bankAt=Date.now()}}).catch(()=>{}).finally(()=>{state.bankLoading=false;if(state.teacherView==='resources')render()}))}const rows=state.bankSummary||[],total=rows.reduce((t,r)=>t+Number(r.total||0),0),mine=rows.reduce((t,r)=>t+Number(r.mine||0),0),pending=(state.pendingBankQuestions||[]).length,bySubject={};rows.forEach(r=>{(bySubject[r.subject]??=[]).push(r)});app.innerHTML=`${teacherHeader('home')}<main class="teacher-page teacher-classes-page"><div class="teacher-screen-title"><div><h1>Recursos</h1><p>Material para acompañar tus clases</p></div></div><section class="teacher-report-grid"><div><b>${total}</b><small>Preguntas en el banco</small></div><div><b>${mine}</b><small>Aportadas por ti</small></div></section>${(()=>{const mats=(state.teacherClasses||[]).flatMap(c=>(c.activities||[]).filter(a=>a.videoMaterial).map(a=>({c,a})));return `<section class="bank-card"><h2 style="margin:0 0 4px;font-size:16px">📎 Materiales que has subido</h2><p style="font-size:12px;color:#5f7468;margin:0 0 8px">Si subiste algo por error, quítalo aquí. Se borra de la nube y tus estudiantes dejan de verlo.</p>${mats.length?mats.map(({c,a})=>`<div class="mat-row"><span class="mat-icon">${String(a.videoMaterial.mime_type||'').startsWith('video/')?'<img src="assets/video-material.png" alt="">':String(a.videoMaterial.mime_type||'').includes('pdf')||/\.pdf$/i.test(a.videoMaterial.file_path||'')?'<img src="assets/pdf-material.png" alt="">':'📄'}</span><span class="mat-copy"><b>${escapeHtml(a.videoMaterial.title||a.title)}</b><small>${escapeHtml(c.grade)} ${escapeHtml(c.sectionLabel)} · ${escapeHtml(a.title)}${a.videoMaterial.file_size?` · ${fmtBytes(a.videoMaterial.file_size)}`:''}</small></span><button class="tar-remove" data-teacher-action="remove-activity" data-class-id="${escapeHtml(c.id)}" data-activity-id="${escapeHtml(a.id)}">Quitar</button></div>`).join(''):'<div class="teacher-mini-empty">Aún no has subido archivos.</div>'}</section>`})()}<section class="bank-card"><h2 style="margin:0 0 4px;font-size:16px">🧠 Banco de preguntas de AulaYa</h2><p style="font-size:12px;color:#5f7468;margin:0 0 8px">Cada pregunta que escribes en una actividad se guarda aquí, organizada por grado, materia y tema. Entre todos los docentes vamos armando un banco cada vez más grande.${pending?` <b>${pending} pregunta(s) se subirán cuando haya internet.</b>`:''}</p>${rows.length?Object.entries(bySubject).map(([subject,list])=>`<div style="margin-top:8px"><span class="subject-chip sc-${subject.normalize('NFD').replace(/[^a-zA-Z]/g,'').toLowerCase()}">${escapeHtml(subjectShort(subject))}</span>${list.map(r=>`<div class="bank-row"><span>${escapeHtml(r.grade)} · ${escapeHtml(r.topic)}</span><b>${r.total} ${Number(r.total)===1?'pregunta':'preguntas'}</b></div>`).join('')}</div>`).join(''):`<div class="teacher-mini-empty">${state.bankLoading?'Cargando el banco…':'Aún no hay preguntas. Cuando crees una actividad con tus propias preguntas, aparecerán aquí.'}</div>`}</section></main>${teacherNav()}`}
function teacherAvatarIndex(){const value=Number.parseInt(state.teacherAvatar,10);return Number.isFinite(value)&&value>=0&&value<8?value:0}
function teacherAvatarPosition(index){return `--avatar-x:${(index%4)/3*100}%;--avatar-y:${Math.floor(index/4)*100}%`}
function teacherNotifications(){const items=state.notifications||[],unread=items.some(item=>!item.read);app.innerHTML=`<header class="teacher-profile-header"><button class="teacher-back" data-teacher-action="home" aria-label="Volver al inicio">‹</button><h1>Notificaciones</h1><span></span></header><main class="teacher-page teacher-profile-page"><div class="section-title"><h2>Tus avisos</h2><button class="mark-all-read" data-action="read-all" ${unread?'':'disabled'}>${unread?'Marcar todas como leídas':'Todas leídas'}</button></div>${items.filter(i=>!(state.dismissedNotices||[]).includes(i.id)).length?`<div class="notice-tools"><small>${items.filter(i=>!(state.dismissedNotices||[]).includes(i.id)).length} notificaciones</small><button class="notice-clear" data-action="clear-read-notices" ${items.some(i=>i.read&&!(state.dismissedNotices||[]).includes(i.id))?'':'disabled'}>🗑 Borrar leídas</button></div>`:''}${items.filter(i=>!(state.dismissedNotices||[]).includes(i.id)).length?items.filter(i=>!(state.dismissedNotices||[]).includes(i.id)).map(item=>`<div class="notice-row welcome-notice" data-notice-id="${escapeHtml(item.id)}"><button class="notice-x" data-delete-notice="${escapeHtml(item.id)}" aria-label="Borrar esta notificación" title="Borrar">✕</button><span class="notice-icon welcome-tiger"><img src="assets/aulaya-mascot.png" alt="Teo, la mascota de Aula ya!"></span><span class="notice-copy"><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.message)}</small>${item.studentId&&item.classId&&(state.teacherClasses||[]).some(c=>c.id===item.classId)?`<button class="reinforce-btn" data-teacher-action="reinforce" data-class-id="${escapeHtml(item.classId)}" data-student-id="${escapeHtml(item.studentId)}" data-reinforce-subject="${escapeHtml(item.subject||'')}">＋ Crear actividad de refuerzo</button>`:''}</span>${item.read?'':'<i class="unread-dot"></i>'}</div>`).join(''):`<div class="empty-state"><div class="empty-icon"><img src="assets/notification-icon.png" alt=""></div><b>No tienes notificaciones</b><p>Los avisos de Aula ya aparecerán aquí.</p></div>`}</main>${teacherNav()}`}
function teacherProfile(){const first=String(state.firstName||state.profile||'Docente').split(/\s+/)[0],rawSubject=(state.teacherSubjects||[])[0]||'Sin materias asignadas',subject=state.variedSubjects?'Materias variadas':(rawSubject==='Ciencias'?'Ciencias Naturales':rawSubject),avatar=teacherAvatarIndex(),avatarOptions=Array.from({length:8},(_,index)=>`<button class="teacher-avatar-choice ${avatar===index?'selected':''}" data-teacher-action="choose-avatar" data-avatar="${index}" aria-pressed="${avatar===index}"><img class="teacher-avatar-choice-image" src="assets/teacher-character-${index+1}.png" alt=""><span class="teacher-avatar-choice-copy"><b>Personaje ${index+1}</b><small>${avatar===index?'Seleccionado':'Elegir esta foto'}</small></span><span class="teacher-avatar-choice-check">${avatar===index?'✓':''}</span></button>`).join('');app.innerHTML=`<header class="teacher-profile-header"><button class="teacher-back" data-teacher-action="home" aria-label="Volver al inicio">‹</button><h1>Perfil</h1><button class="teacher-notice" data-teacher-action="notifications" aria-label="Notificaciones"><img class="teacher-bell-icon" src="assets/notification-icon.png" alt="">${hasUnreadNotifications()?'<i class="notif-dot"></i>':''}</button></header><main class="teacher-page teacher-profile-page"><section class="teacher-profile-hero"><div class="teacher-profile-card-art"><button class="teacher-profile-avatar" data-teacher-action="open-avatar-picker" aria-label="Cambiar foto de perfil" aria-expanded="${Boolean(state.teacherAvatarPickerOpen)}"><img src="assets/teacher-character-${avatar+1}.png" alt=""></button><div class="teacher-profile-copy"><h2>Profe ${escapeHtml(first)}</h2><p>Docente</p><span class="teacher-subject"><i>🍃</i>${escapeHtml(subject)}</span></div><button class="teacher-edit-profile" data-teacher-action="edit-profile" aria-label="Editar perfil">✎</button><div class="profile-card-hill"></div><div class="profile-card-leaves"></div></div></section>${state.teacherAvatarPickerOpen?`<section class="teacher-photo-section" id="teacher-photo-picker"><div class="teacher-photo-heading"><h2>Elige tu foto de perfil</h2><p>Toca la opción que quieras usar</p></div><div class="teacher-avatar-picker-grid">${avatarOptions}</div></section>`:''}<section class="teacher-profile-options"><button data-teacher-action="profile-info"><span>♙</span><b>Información personal</b><i>›</i></button><button data-teacher-action="profile-password"><span>▣</span><b>Cambiar contraseña</b><i>›</i></button><button data-teacher-action="profile-preferences"><span>⚙</span><b>Preferencias</b><i>›</i></button><button data-teacher-action="profile-help"><span>ⓘ</span><b>Ayuda y soporte</b><i>›</i></button><button class="profile-logout" data-teacher-action="logout"><span>⇥</span><b>Cerrar sesión</b><i>›</i></button></section></main>${teacherNav('profile')}<img class="teacher-profile-corner-plants" src="assets/profile-corner-plants.png" alt="">`}
function teacherBlank(){if(state.teacherView==='profile'){teacherProfile();return}if(state.teacherView==='notifications'){teacherNotifications();return}if(state.teacherView==='classes'){teacherClasses();return}if(state.teacherView==='detail'){teacherClassDetail();return}if(state.teacherView==='students'){teacherStudents();return}if(state.teacherView==='reports'){teacherReports();return}if(state.teacherView==='student-report'){teacherStudentReport();return}if(state.teacherView==='resources'){teacherResources();return}const first=String(state.firstName||state.profile||'Docente').split(/\s+/)[0],courses=state.teacherCourses||[],subjects=state.teacherSubjects||[],school=state.school?.name||'Tu institución educativa',classes=state.teacherClasses||[],cards=classes.slice(0,3).map((item,index)=>`<button class="teacher-class-card" data-teacher-action="open-class" data-class-id="${escapeHtml(item.id)}">${teacherClassIcon(item,`color-${index%5}`)}<span class="teacher-class-copy"><b>${escapeHtml(item.grade)} ${escapeHtml(item.sectionLabel)}</b><small>${(item.subjects||[]).map(escapeHtml).join(' · ')||'Materias por organizar'}</small><small>${(item.students||[]).length} ${(item.students||[]).length===1?'estudiante':'estudiantes'}</small></span><span class="teacher-card-arrow">›</span></button>`).join('');app.innerHTML=`${teacherHeader()}<main class="teacher-page"><section class="teacher-welcome"><img src="assets/aulaya-mascot.png" alt="Teo, el jaguar de Aula ya!"><div><span class="teacher-welcome-greeting">Hola, Profe ${escapeHtml(first)}</span><h1>Gestiona<br>tus clases</h1><p>y acompaña el aprendizaje de tus estudiantes.</p></div></section><section class="teacher-shortcuts"><button data-teacher-action="classes"><span><img src="assets/mis-clases.png" alt=""></span><b>Mis clases</b></button><button data-teacher-action="students"><span><img src="assets/estudiantes.png" alt=""></span><b>Estudiantes</b></button><button data-teacher-action="reports"><span><img src="assets/reportes.png" alt=""></span><b>Reportes</b></button><button data-teacher-action="resources"><span><img src="assets/recursos.png" alt=""></span><b>Recursos</b></button></section><div class="teacher-section-title"><h2>Mis clases</h2><button data-teacher-action="add-class">＋ Crear clase</button></div><section class="teacher-class-list">${cards||`<div class="teacher-mini-empty">Aún no tienes clases. <button data-teacher-action="classes">Ver clases</button></div>`}</section></main>${teacherNav()}`}
function showTeacherActivityModal(classId=''){if(!(state.teacherClasses||[]).length){state.teacherView='classes';render();toastMsg('Crea una clase antes de preparar una actividad.');return}state.modal={type:'teacher-activity',classId};render()}
function classSubjectOptions(){const reg=state.teacherSubjects||[];return state.variedSubjects||!reg.length?['Matemáticas','Lengua','Ciencias','Inglés','Ciencias Sociales']:['Matemáticas','Lengua','Ciencias','Inglés','Ciencias Sociales'].filter(x=>reg.includes(x))}
function subjectPickerMarkup(selected,legend){const opts=classSubjectOptions(),sel=selected&&selected.length?selected:opts;return `<fieldset class="teacher-subject-picker"><legend>${legend||'Materias de la clase'} <small>(elige al menos una)</small></legend><label class="subject-all"><input type="checkbox" id="teacher-class-all-subjects" ${opts.every(x=>sel.includes(x))?'checked':''}> <b>Todas las materias</b></label><div class="subject-toggles">${opts.map(subject=>`<label class="subject-toggle"><input type="checkbox" name="teacher-class-subject" value="${escapeHtml(subject)}" ${sel.includes(subject)?'checked':''}>${subjectIcon(subject,'st-ico')}<span>${escapeHtml(subjectShort(subject))}</span><i>✓</i></label>`).join('')}</div></fieldset>`}
function subjectShort(x){return x==='Lengua'?'Lenguaje':x==='Ciencias Sociales'?'Sociales':x}
function subjectChips(list){return (list||[]).map(x=>`<span class="subject-chip sc-${escapeHtml(x.normalize('NFD').replace(/[^a-zA-Z]/g,'').toLowerCase())}">${subjectIcon(x,'chip-ico')}${escapeHtml(subjectShort(x))}</span>`).join('')}
function showTeacherClassModal(){const grades=teacherClassOptions(),subjects=state.teacherSubjects||[],options=grades.map(grade=>`<option value="${escapeHtml(grade)}">${escapeHtml(grade)}</option>`).join('');state.modal={type:'teacher-class',grades,subjects:classSubjectOptions()};render()}
function saveTeacherClass(){const grade=document.querySelector('input[name="tc-grade"]:checked')?.value||document.querySelector('#teacher-class-grade')?.value||'',sectionType=document.querySelector('#teacher-section-type')?.value||'letter',section=document.querySelector('#teacher-section-value')?.value.trim()||'',subjects=[...document.querySelectorAll('input[name="teacher-class-subject"]:checked')].map(input=>input.value);if(!grade){toastMsg('Selecciona el grado de la clase.');return}if(!subjects.length){toastMsg('Elige al menos una materia para la clase.');return}const valid=sectionType==='letter'?/^[A-Za-zÁÉÍÓÚÑáéíóúñ]$/.test(section):/^\d{1,2}$/.test(section);if(!valid){toastMsg(sectionType==='letter'?'Escribe una sola letra para la sección.':'Escribe un número de sección válido.');return}const label=sectionType==='letter'?section.toUpperCase():section;if((state.teacherClasses||[]).some(item=>item.grade===grade&&item.sectionType===sectionType&&item.sectionLabel===label)){toastMsg(`Ya existe ${grade} ${label}.`);return}state.teacherClasses??=[];state.teacherClasses.push({id:`class-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`,grade,sectionType,sectionLabel:label,subjects,students:[],createdAt:new Date().toISOString()});state.teacherView='classes';state.modal=null;saveState();render();toastMsg(`Clase ${grade} ${label} creada.`)}
function renderEligibleStudentResults(message='',students=[]){const box=document.querySelector('#teacher-student-results');if(!box)return;if(message){box.innerHTML=`<div class="teacher-student-search-hint">${escapeHtml(message)}</div>`;return}const q=String(document.querySelector('#teacher-student-search')?.value||'').trim(),mark=t=>{const txt=String(t||''),k=txt.toLowerCase().indexOf(q.toLowerCase());return k<0||!q?escapeHtml(txt):`${escapeHtml(txt.slice(0,k))}<mark>${escapeHtml(txt.slice(k,k+q.length))}</mark>${escapeHtml(txt.slice(k+q.length))}`};box.innerHTML=students.length?`<small class="sugg-count">${students.length===1?'1 estudiante encontrado':`${students.length} estudiantes encontrados`} · toca para agregar</small>`+students.map(student=>`<button class="teacher-eligible-student sugg" data-eligible-student="${escapeHtml(student.student_id)}"><span class="rp-avatar stu-photo">${studentFace(student.student_id)}</span><span class="sugg-copy"><b>${mark(student.student_name||'Estudiante')}</b><small>${mark(student.student_email)}</small><em>${escapeHtml(student.student_grade||'Grado sin indicar')}</em></span><i>＋ Agregar</i></button>`).join(''):'<div class="teacher-student-search-hint">No encontramos estudiantes con ese nombre o correo en tu institución, o ya están en esta clase.</div>'}
let eligibleStudentTimer=null;
const STUDENT_EMAIL_RE=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
async function searchEligibleStudents(){const input=document.querySelector('#teacher-student-search'),query=(input?.value||'').trim(),classId=state.modal?.classId;if(query.length<3){renderEligibleStudentResults('Escribe al menos 3 letras del nombre o del correo.');return}renderEligibleStudentResults('Buscando…');try{if(!state.modal?.synced){await window.aulayaDb.saveProfile(cloudProfilePayload());if(state.modal)state.modal.synced=true}const students=await window.aulayaDb.findEligibleStudents(classId,query.toLowerCase());if((input?.value||'').trim()!==query)return;const ql=query.toLowerCase(),score=st=>String(st.student_email||'').toLowerCase()===ql?0:String(st.student_name||'').toLowerCase().startsWith(ql)?1:2,list=[...(students||[])].sort((a,b)=>score(a)-score(b)||String(a.student_name).localeCompare(String(b.student_name)));state.eligibleStudentResults=list;renderEligibleStudentResults('',list)}catch(error){renderEligibleStudentResults(error.message||'No se pudo buscar. Revisa tu conexión e inténtalo de nuevo.')}}
async function saveTeacherStudent(studentId){const classId=state.modal?.classId,item=(state.teacherClasses||[]).find(entry=>entry.id===classId);if(!item){toastMsg('No encontramos esa clase.');return}const eligible=(state.eligibleStudentResults||[]).find(student=>student.student_id===studentId);if(!eligible){toastMsg('Vuelve a buscar esa cuenta antes de agregarla.');return}if((item.students||[]).some(student=>student.id===studentId)){toastMsg('Ese estudiante ya está en la clase.');return}try{const added=await window.aulayaDb.addStudentToClass(item.id,studentId);if(!added)throw new Error('No se confirmó la inscripción. Vuelve a buscar el estudiante.');item.students??=[];item.students.push({id:added.student_id,email:added.student_email,name:added.student_name,grade:added.student_grade,createdAt:new Date().toISOString()});state.teacherClassId=item.id;state.teacherView='detail';state.modal=null;state.eligibleStudentResults=[];saveState();render();toastMsg(`${added.student_name} se agregó a ${item.grade} ${item.sectionLabel}.`)}catch(error){toastMsg(error.message||'No se pudo agregar al estudiante.')}}

async function flushBankQuestions(){const rows=state.pendingBankQuestions||[];if(!rows.length||!navigator.onLine||!window.aulayaDb?.addBankQuestions||!window.aulayaDb.userId?.())return;try{await window.aulayaDb.addBankQuestions(rows);state.pendingBankQuestions=[];saveState()}catch(error){console.warn('Las preguntas quedan pendientes para el banco:',error)}}
async function removeTeacherActivity(classId,activityId,onlyFile){const item=(state.teacherClasses||[]).find(entry=>entry.id===classId),act=(item?.activities||[]).find(a=>a.id===activityId);if(!item||!act){state.modal=null;render();return}const mat=act.videoMaterial;if(mat){if(!navigator.onLine||!window.aulayaDb?.isConfigured()){toastMsg('Necesitas internet para quitar el archivo. Inténtalo cuando vuelvas a conectarte.');return}document.querySelectorAll('[data-teacher-action^="confirm-remove"]').forEach(b=>{b.disabled=true});try{if(mat.id)await window.aulayaDb.deleteClassMaterial(mat.id);if(mat.file_path)await window.aulayaDb.deleteClassVideo(mat.file_path)}catch(error){document.querySelectorAll('[data-teacher-action^="confirm-remove"]').forEach(b=>{b.disabled=false});toastMsg(error.message||'No se pudo quitar el archivo. Inténtalo de nuevo.');return}}if(onlyFile){act.videoMaterial=null}else{item.activities=item.activities.filter(a=>a.id!==activityId)}state.modal=null;saveState();render();toastMsg(onlyFile?'Archivo quitado. La actividad sigue publicada.':'Actividad quitada. Tus estudiantes dejarán de verla.')}
async function saveTeacherActivity(){const customQ=readTeacherQuestions();if(customQ.error){toastMsg(customQ.error);return}const title=document.querySelector('#teacher-activity-title')?.value.trim()||'',description=document.querySelector('#teacher-activity-description')?.value.trim()||'',classId=state.modal?.classId||state.modal?.selectedClassId||document.querySelector('#teacher-activity-class')?.value,item=(state.teacherClasses||[]).find(entry=>entry.id===classId),topics=teacherActivityTopics(classId),topic=topics[Number(document.querySelector('#teacher-activity-topic')?.value)];if(!item){toastMsg('Selecciona una clase.');return}if(!topic){toastMsg('Selecciona un tema disponible para esta clase.');return}if(title.length<3){toastMsg('Escribe un título para la actividad.');return}const audience=document.querySelector('input[name="tq-audience"]:checked')?.value||'all',chosen=[...document.querySelectorAll('input[name="tq-student"]:checked')],assignedTo=audience==='some'?chosen.map(i=>i.value):[],assignedNames=audience==='some'?chosen.map(i=>i.dataset.name):[];if(audience==='some'&&!assignedTo.length){toastMsg('Elige al menos un estudiante o marca «Toda la clase».');return}if(activityFileProblem(stagedTeacherVideo)){toastMsg(activityFileProblem(stagedTeacherVideo));return}const button=document.querySelector('[data-action="save-teacher-activity"]');if(button){button.disabled=true;button.textContent=stagedTeacherVideo?'Subiendo archivo…':'Guardando…'}let material=null;try{let pendingFile=null;const newActId=`activity-${Date.now().toString(36)}`;if(stagedTeacherVideo&&!navigator.onLine){const key=`pending-file-${newActId}`;await storeOfflineVideo(key,stagedTeacherVideo);pendingFile={key,name:stagedTeacherVideo.name,type:stagedTeacherVideo.type||'application/octet-stream',size:stagedTeacherVideo.size,classId:item.id};}else if(stagedTeacherVideo){if(!window.aulayaDb?.isConfigured())throw new Error('Se necesita la conexión a Supabase para compartir el archivo.');await window.aulayaDb.saveProfile(cloudProfilePayload());const id=window.crypto?.randomUUID?window.crypto.randomUUID():`video-${Date.now().toString(36)}`,path=`${window.aulayaDb.userId()}/${item.id}/${id}.${fileExtension(stagedTeacherVideo.name)}`;await window.aulayaDb.uploadClassVideo(path,stagedTeacherVideo);try{material=await window.aulayaDb.createClassMaterial({teacher_id:window.aulayaDb.userId(),teacher_class_id:item.id,title,description,grade:topic.grade,subject:topic.subject,topic:topic.topic,file_path:path,mime_type:stagedTeacherVideo.type||'application/octet-stream',file_size:stagedTeacherVideo.size})}catch(error){await window.aulayaDb.deleteClassVideo(path);throw error}if(!material){await window.aulayaDb.deleteClassVideo(path);throw new Error('El archivo se subió, pero no se pudo publicar para la clase.')}}item.activities??=[];item.activities.push({id:newActId,title,description,questions:customQ.questions,grade:topic.grade,subject:topic.subject,topic:topic.topic,videoMaterial:material,...(pendingFile?{pendingFile}:{}),assignedTo,assignedNames,createdAt:new Date().toISOString()});if(customQ.questions.length){state.pendingBankQuestions=[...(state.pendingBankQuestions||[]),...customQ.questions.map(q=>({grade:topic.grade,subject:topic.subject,topic:topic.topic,question:q.question,answers:q.answers,correct:q.correct}))];setTimeout(flushBankQuestions,400)}clearStagedTeacherVideo();state.teacherClassId=item.id;state.teacherView='detail';state.modal=null;saveState();render();if(pendingFile)showSyncPop('Sin internet: tu material se subirá después 📴','Lo guardamos en este dispositivo. Cuando vuelva la conexión se sube solito y te avisamos.');else if(!navigator.onLine)showSyncPop('Actividad guardada en tu dispositivo 📴','Se publicará para tus estudiantes cuando vuelva el internet.');else toastMsg(material?`Archivo compartido con ${item.grade} ${item.sectionLabel}.`:`Actividad de ${topic.topic} creada.`)}catch(error){if(button){button.disabled=false;button.textContent='Guardar actividad'}toastMsg(error.message||'No se pudo guardar la actividad.')}}
function teacherActivityModalMarkup(m){const classes=state.teacherClasses||[],classId=m.classId||m.selectedClassId||classes[0]?.id||'',selectedClass=classes.find(item=>item.id===classId),topics=teacherActivityTopics(classId);return `<div class="modal-grabber"></div><h2>Crear actividad</h2><p>Elige un único tema del temario piloto para compartir con tu clase.</p>${m.classId?`<p class="teacher-selected-class">Clase: <b>${escapeHtml(selectedClass?.grade||'')} ${escapeHtml(selectedClass?.sectionLabel||'')}</b></p>`:`<label class="teacher-form-label">Clase<select class="form-input" id="teacher-activity-class">${classes.map(item=>`<option value="${escapeHtml(item.id)}" ${item.id===classId?'selected':''}>${escapeHtml(item.grade)} ${escapeHtml(item.sectionLabel)}</option>`).join('')}</select></label>`}<label class="teacher-form-label">Curso, materia y tema<select class="form-input" id="teacher-activity-topic" ${topics.length?'':'disabled'}>${topics.length?topics.map((entry,index)=>`<option value="${index}" ${m.subject&&entry.subject===m.subject&&topics.findIndex(t=>t.subject===m.subject)===index?'selected':''}>${escapeHtml(entry.grade)} · ${escapeHtml(entry.subject==='Lengua'?'Lenguaje':entry.subject==='Ciencias Sociales'?'Sociales':entry.subject)} · ${escapeHtml(entry.topic)}</option>`).join(''):'<option value="">No hay temas disponibles para esta clase</option>'}</select></label>${(()=>{const studs=selectedClass?classProgressInfo(selectedClass).students:[],some=(m.forStudents||[]).length>0;return `<fieldset class="audience-picker"><legend>¿Para quién es?</legend><label><input type="radio" name="tq-audience" value="all" ${some?'':'checked'}> Toda la clase</label><label><input type="radio" name="tq-audience" value="some" ${some?'checked':''} ${studs.length?'':'disabled'}> Solo algunos estudiantes ${studs.length?'':'<small>(agrega estudiantes primero)</small>'}</label><div class="aud-list" ${some?'':'hidden'}>${studs.map(st=>`<label><input type="checkbox" name="tq-student" value="${escapeHtml(st.id)}" data-name="${escapeHtml(st.name||'Estudiante')}" ${(m.forStudents||[]).includes(st.id)?'checked':''}> ${escapeHtml(st.name||'Estudiante')}${st.pct!==null&&st.pct!==undefined?` <small>· ${st.pct}%</small>`:''}</label>`).join('')}</div></fieldset>`})()}<label class="teacher-form-label">Título de la actividad<input class="form-input" id="teacher-activity-title" maxlength="80" value="${m.reinforce?'Refuerzo especial':''}" placeholder="Ej. Exploremos ${escapeHtml(topics[0]?.topic||'el tema')}"></label><label class="teacher-form-label">Instrucciones <small>(opcional)</small><textarea class="form-input teacher-textarea" id="teacher-activity-description" maxlength="300" placeholder="¿Qué deben hacer tus estudiantes?"></textarea></label><div class="teacher-custom-questions"><div class="tq-head"><b>Preguntas propias <small>(opcional · hasta 5)</small></b><small>Escribe la pregunta, 3 opciones y marca la correcta.</small></div><div id="tq-list">${teacherQuestionBlock(0)}</div><button type="button" class="tq-add" data-action="add-teacher-question">＋ Agregar otra pregunta</button></div><div class="teacher-topic-includes"><b>Cada tema ya incluye para tus estudiantes:</b><span>🎬 Video recomendado</span><span>🎮 Juego del tema</span><span>❓ 5 preguntas de práctica</span><small>Si quieres, agrega abajo tu propio material.</small></div><div class="teacher-form-label teacher-upload-field">Archivo para la clase <small>(opcional · video, PDF, imagen, documento… · máximo 20 MB)</small><input class="upload-input" id="teacher-activity-video" type="file"><label class="upload-button" for="teacher-activity-video"><svg viewBox="0 0 48 40" aria-hidden="true"><path d="M14 30H11a8 8 0 0 1-1.2-15.9A11 11 0 0 1 31 9.6a9 9 0 0 1 7 16.6c-1 .6-2.2 .9-3.4.9H34" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/><path d="M24 36V19M17.5 25.5 24 19l6.5 6.5" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/></svg>Subir archivo</label><small id="teacher-video-file-name">${stagedTeacherVideo?stagedFileMarkup(stagedTeacherVideo):'El estudiante podrá descargarlo para usarlo sin internet.'}</small></div>${stagedTeacherVideoUrl&&previewMarkup(stagedTeacherVideo,stagedTeacherVideoUrl)?`<div class="teacher-video-preview-wrap"><b>Vista previa</b>${previewMarkup(stagedTeacherVideo,stagedTeacherVideoUrl)}</div>`:''}<div class="modal-actions"><button class="wide-button" data-action="save-teacher-activity" ${topics.length?'':'disabled'}>Guardar actividad</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function schoolDisplay(school){return `${school.name}${school.area?` · ${school.area}`:''} · ${school.municipality}, ${school.department}`}
function paintSchoolResults(message=''){const box=document.querySelector('#school-results');if(!box)return;if(message){box.innerHTML=`<div class="school-hint">${escapeHtml(message)}</div>`;return}if(state.schoolLoading){box.innerHTML='<div class="school-hint">Cargando instituciones…</div>';return}box.innerHTML=state.schoolResults.length?`<div class="school-hint">${state.schoolResults.length} instituciones disponibles para seleccionar.</div>`:'<div class="school-hint">No encontramos instituciones para esta ubicación.</div>'}
function soqlString(value){return String(value||'').replaceAll("'","''")}
function normalizeLocation(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase()}
function areaLabel(value){const raw=String(value||'').trim(),type=/^(COR\.?\s|CORREGIMIENTO\b)/i.test(raw)?'Corregimiento':'Vereda',name=raw.replace(/^(COR\.?|CORREGIMIENTO|VEREDA|VDA\.?|VER\.)\s*/i,'').replace(/^DE\s+/i,'');return `${type} ${name.toLocaleLowerCase('es').replace(/(^|[\s-])\p{L}/gu,letter=>letter.toLocaleUpperCase('es'))}`}
let schoolSearchTimer=null,schoolSearchRequest=0,departmentRequest=0,areaRequest=0,schoolListRequest=0;
async function loadSchoolDepartments(){if(state.schoolDepartments.length||state.schoolDepartmentsLoaded||state.schoolLoadingDepartments)return;state.schoolLoadingDepartments=true;const select=document.querySelector('#school-department');if(select){select.disabled=true;select.innerHTML='<option value="">Cargando departamentos…</option>'}try{const params=new URLSearchParams({$select:'distinct departamento',$where:'departamento IS NOT NULL',$order:'departamento',$limit:'40'});const response=await fetch(`https://www.datos.gov.co/resource/cfw5-qzt5.json?${params}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('api');state.schoolDepartments=(await response.json()).map(row=>row.departamento).filter(Boolean).sort((a,b)=>a.localeCompare(b,'es'));if(!state.schoolDepartments.length)throw new Error('empty');state.schoolDepartmentsLoaded=true;state.schoolDepartmentsError=false;if(select){select.disabled=false;select.innerHTML='<option value="">Selecciona un departamento</option>'+state.schoolDepartments.map(name=>`<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('')}}catch(_){state.schoolDepartmentsError=true;state.schoolDepartments=['AMAZONAS','ANTIOQUIA','ARAUCA','ATLÁNTICO','BOGOTÁ D.C.','BOLÍVAR','BOYACÁ','CALDAS','CAQUETÁ','CASANARE','CAUCA','CESAR','CHOCÓ','CÓRDOBA','CUNDINAMARCA','GUAINÍA','GUAVIARE','HUILA','LA GUAJIRA','MAGDALENA','META','NARIÑO','NORTE DE SANTANDER','PUTUMAYO','QUINDÍO','RISARALDA','SAN ANDRÉS Y PROVIDENCIA','SANTANDER','SUCRE','TOLIMA','VALLE DEL CAUCA','VAUPÉS','VICHADA'];if(select){select.disabled=false;select.innerHTML='<option value="">Selecciona un departamento</option>'+state.schoolDepartments.map(name=>`<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('')}}finally{state.schoolLoadingDepartments=false}}
function readLocationCache(key){try{const saved=JSON.parse(localStorage.getItem(key)||'null');return Array.isArray(saved)?saved:null}catch(_){return null}}
function writeLocationCache(key,items){try{localStorage.setItem(key,JSON.stringify(items))}catch(_){}}
function locationOptions(items,label,format=name=>name){return `<option value="">${label}</option>`+items.map(name=>`<option value="${escapeHtml(name)}">${escapeHtml(format(name))}</option>`).join('')}
function schoolSelectOptions(items,label){return `<option value="">${label}</option>`+items.map((school,index)=>`<option value="${index}">${escapeHtml(school.name)}</option>`).join('')}
async function loadSchoolMunicipalities(department){const request=++departmentRequest,select=document.querySelector('#school-municipality'),cacheKey=`aulaya-municipalities-${normalizeLocation(department)}`;state.schoolDepartmentCanonical=department;const cached=readLocationCache(cacheKey);state.schoolMunicipalities=cached||[];state.schoolLoadingMunicipalities=!cached;if(select){select.disabled=false;select.innerHTML=locationOptions(state.schoolMunicipalities,cached?'Selecciona un municipio':'Cargando municipios…')}try{const params=new URLSearchParams({$select:'distinct municipio',$where:`departamento = '${soqlString(department)}' AND municipio IS NOT NULL`,$limit:'500'});const response=await fetch(`https://www.datos.gov.co/resource/cfw5-qzt5.json?${params}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('api');const rows=await response.json();if(request!==departmentRequest)return;state.schoolMunicipalities=[...new Map(rows.map(row=>row.municipio).filter(Boolean).map(name=>[normalizeLocation(name),name])).values()].sort((a,b)=>a.localeCompare(b,'es'));state.schoolLoadingMunicipalities=false;writeLocationCache(cacheKey,state.schoolMunicipalities);if(select){select.disabled=false;select.innerHTML=locationOptions(state.schoolMunicipalities,'Selecciona un municipio');if(state.schoolMunicipality&&state.schoolMunicipalities.some(name=>normalizeLocation(name)===normalizeLocation(state.schoolMunicipality)))select.value=state.schoolMunicipality}}catch(_){if(request!==departmentRequest)return;state.schoolLoadingMunicipalities=false;if(select){select.disabled=false;select.innerHTML=locationOptions(state.schoolMunicipalities,state.schoolMunicipalities.length?'Selecciona un municipio':'No se pudieron cargar; verifica tu conexión')}}}
async function loadSchoolAreas(){const request=++areaRequest,department=state.schoolDepartmentCanonical||state.schoolDepartment,municipality=state.schoolMunicipality,select=document.querySelector('#school-area'),cacheKey=`aulaya-areas-${normalizeLocation(department)}-${normalizeLocation(municipality)}`;const cached=readLocationCache(cacheKey);state.schoolAreas=cached||[];if(select){select.disabled=false;select.innerHTML=locationOptions(state.schoolAreas,'Sin especificar',areaLabel)}try{const params=new URLSearchParams({$select:'distinct barrio_vereda',$where:`departamento = '${soqlString(department)}' AND municipio = '${soqlString(municipality)}' AND barrio_vereda IS NOT NULL`,$limit:'1000'});const response=await fetch(`https://www.datos.gov.co/resource/cfw5-qzt5.json?${params}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('api');const rows=await response.json();if(request!==areaRequest)return;state.schoolAreas=[...new Set(rows.map(row=>row.barrio_vereda).filter(name=>/^(COR\.?\s|CORREGIMIENTO\b|VEREDA\b|VDA\.?\s|VER\.\s)/i.test(name)&&!/(^|\s)(BARRIO|B\.)($|\s)/i.test(name)))].sort((a,b)=>a.localeCompare(b,'es'));if(department==='Santander'&&['Suaita','Guavatá'].includes(municipality)&&!state.schoolAreas.some(name=>/VADO\s+REAL/i.test(name)))state.schoolAreas.push('COR. VADO REAL');writeLocationCache(cacheKey,state.schoolAreas);if(select){select.disabled=false;select.innerHTML=locationOptions(state.schoolAreas,'Sin especificar',areaLabel);if(state.schoolArea)select.value=state.schoolArea}}catch(_){if(request!==areaRequest)return;state.schoolAreas=state.schoolAreas.length?state.schoolAreas:(department==='Santander'&&['Suaita','Guavatá'].includes(municipality)?['COR. VADO REAL']:[]);if(select){select.disabled=false;select.innerHTML=locationOptions(state.schoolAreas,'Sin especificar',areaLabel)}}}
async function loadSchools(){const request=++schoolListRequest,department=state.schoolDepartmentCanonical||state.schoolDepartment,municipality=state.schoolMunicipality,area=state.schoolArea,select=document.querySelector('#school-search'),cacheKey=`aulaya-schools-${normalizeLocation(department)}-${normalizeLocation(municipality)}-${normalizeLocation(area)}`;state.schoolResults=readLocationCache(cacheKey)||[];state.schoolSelected=null;state.schoolLoading=true;if(select){select.disabled=false;select.innerHTML=schoolSelectOptions(state.schoolResults,state.schoolResults.length?'Selecciona una institución':'Cargando instituciones…')}paintSchoolResults();let where=`departamento = '${soqlString(department)}' AND municipio = '${soqlString(municipality)}' AND nombre_establecimiento IS NOT NULL`;if(area)where+=` AND barrio_vereda = '${soqlString(area)}'`;try{const params=new URLSearchParams({$select:'distinct codigo_dane,nombre_establecimiento,municipio,departamento,barrio_vereda',$where:where,$limit:'1000'});const response=await fetch(`https://www.datos.gov.co/resource/cfw5-qzt5.json?${params}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('api');const rows=await response.json();if(request!==schoolListRequest)return;const unique=new Map();rows.forEach(row=>{const key=String(row.codigo_dane||row.nombre_establecimiento);if(!unique.has(key))unique.set(key,{code:row.codigo_dane,name:row.nombre_establecimiento,municipality:row.municipio,department:row.departamento,area:row.barrio_vereda||''})});state.schoolResults=[...unique.values()].sort((a,b)=>a.name.localeCompare(b.name,'es'));state.schoolLoading=false;writeLocationCache(cacheKey,state.schoolResults);if(state.schoolSelected){const selectedIndex=state.schoolResults.findIndex(school=>school.code===state.schoolSelected.code&&school.name===state.schoolSelected.name);if(selectedIndex<0)state.schoolSelected=null}if(select){select.disabled=!state.schoolResults.length;select.innerHTML=schoolSelectOptions(state.schoolResults,state.schoolResults.length?'Selecciona una institución':'No hay instituciones para esta selección');if(state.schoolSelected){const selectedIndex=state.schoolResults.findIndex(school=>school.code===state.schoolSelected.code&&school.name===state.schoolSelected.name);if(selectedIndex>=0)select.value=String(selectedIndex)}}paintSchoolResults()}catch(_){if(request!==schoolListRequest)return;state.schoolLoading=false;if(select){select.disabled=!state.schoolResults.length;select.innerHTML=schoolSelectOptions(state.schoolResults,state.schoolResults.length?'Selecciona una institución':'No se pudo cargar el directorio')}paintSchoolResults(state.schoolResults.length?'Instituciones guardadas disponibles.':'No se pudo consultar el directorio. Comprueba tu conexión e inténtalo de nuevo.')}}

function authScreen(){if(state.authMode==='recover'||state.authMode==='reset'){const reset=state.authMode==='reset';shell(`<div class="auth-content">${heading('Recuperar contraseña','auth-start')}<div class="auth-card"><img class="auth-logo" src="assets/aulaya-logo-white.png" alt="Aula ya!"><h2>${reset?'Elige una contraseña nueva':'¿Olvidaste tu contraseña?'}</h2><p>${reset?'Escribe y confirma tu nueva contraseña.':'Te enviaremos un enlace seguro al correo de tu cuenta.'}</p><div class="auth-fields">${reset?`<label>Nueva contraseña<input class="form-input" id="new-password" type="password" autocomplete="new-password" placeholder="Mínimo 8 caracteres"></label><label>Confirma la contraseña<input class="form-input" id="confirm-new-password" type="password" autocomplete="new-password" placeholder="Repite la contraseña"></label>`:`<label>Correo electrónico<input class="form-input" id="auth-email" type="email" autocomplete="email" value="${escapeHtml(state.authPendingEmail||'')}" placeholder="nombre@correo.com"></label>`}</div><p class="auth-message" id="auth-message" role="alert" ${state.authMessage?'':'hidden'}>${escapeHtml(state.authMessage)}</p><button class="wide-button" data-action="${reset?'save-password':'send-reset'}">${reset?'Guardar contraseña':'Enviar enlace de recuperación'}</button><button class="wide-button secondary" data-auth-mode="login">Volver a iniciar sesión</button></div></div>`);return}const creating=state.authMode==="create",teacher=state.authRole==="teacher",roleName=teacher?"docente":"estudiante",courseOptions=["Primero","Segundo","Tercero","Cuarto","Quinto"],subjectOptions=["Matemáticas","Lengua","Ciencias","Inglés","Ciencias Sociales"];const schoolFields=`<label>Departamento<select class="form-input" id="school-department"><option value="">Selecciona un departamento</option>${state.schoolDepartments.map(name=>`<option value="${escapeHtml(name)}" ${state.schoolDepartment===name?"selected":""}>${escapeHtml(name)}</option>`).join("")}</select></label><label>Municipio<select class="form-input" id="school-municipality" ${state.schoolDepartment?"":"disabled"}><option value="">${state.schoolDepartment?"Selecciona un municipio":"Primero selecciona el departamento"}</option>${state.schoolMunicipalities.map(name=>`<option value="${escapeHtml(name)}" ${state.schoolMunicipality===name?"selected":""}>${escapeHtml(name)}</option>`).join("")}</select></label><label>Corregimiento o vereda <small>(opcional)</small><select class="form-input" id="school-area" ${state.schoolMunicipality?"":"disabled"}><option value="">${state.schoolMunicipality?"Sin especificar":"Primero selecciona el municipio"}</option>${state.schoolAreas.map(name=>`<option value="${escapeHtml(name)}" ${state.schoolArea===name?"selected":""}>${escapeHtml(areaLabel(name))}</option>`).join("")}</select></label><label>Institución educativa<select class="form-input" id="school-search" ${state.schoolMunicipality?"":"disabled"}><option value="">${state.schoolMunicipality?"Selecciona una institución":"Primero selecciona el municipio"}</option>${state.schoolResults.map((school,index)=>`<option value="${index}" ${state.schoolSelected?.code===school.code&&state.schoolSelected?.name===school.name?"selected":""}>${escapeHtml(school.name)}</option>`).join("")}</select><div id="school-results" class="school-results"></div><small class="school-source">Directorio nacional del Ministerio de Educación · <a href="https://www.datos.gov.co/en/Educaci-n/MEN_ESTABLECIMIENTOS_EDUCATIVOS_PREESCOLAR_B-SICA_/cfw5-qzt5" target="_blank" rel="noopener">ver fuente</a></small></label>`;const roleFields=teacher?`<fieldset class="registration-options"><legend>¿Qué grados dictas?</legend><label class="check-option"><input type="checkbox" id="all-primary"> Toda primaria (1.º a 5.º)</label><div class="check-grid">${courseOptions.map(course=>`<label class="check-option"><input type="checkbox" name="teacher-course" value="${course}"> ${course}</label>`).join("")}</div></fieldset><fieldset class="registration-options"><legend>¿Qué materias dictas?</legend><div class="check-grid">${subjectOptions.map(subject=>`<label class="check-option"><input type="checkbox" name="teacher-subject" value="${subject}"> ${subject==='Inglés'?'Inglés (profe de inglés)':subject}</label>`).join("")}</div><label class="check-option"><input type="checkbox" id="varied-subjects"> Materias variadas / varias materias</label></fieldset>`:`<label>Curso o grado<select class="form-input" id="auth-grade"><option value="">Selecciona tu curso</option>${courseOptions.map(course=>`<option value="${course}">${course}</option>`).join("")}</select></label>`;shell(`<div class="auth-content">${heading("Tu cuenta","auth-start")}<div class="auth-card"><img class="auth-logo" src="assets/aulaya-logo-white.png" alt="Aula ya!"><h2>${creating?`Crea tu cuenta de ${roleName}`:"Inicia sesión"}</h2><p>${creating?(teacher?"Cuéntanos qué grados y materias enseñas.":"Guarda tu progreso y personaliza a Teo."):(teacher?"Continúa en tu espacio docente.":"Continúa aprendiendo donde lo dejaste.")}</p><div class="auth-switch"><button class="${creating?"active":""}" data-auth-mode="create">Crear cuenta</button><button class="${!creating?"active":""}" data-auth-mode="login">Iniciar sesión</button></div><div class="auth-fields">${creating?`<label>Nombres<input class="form-input" id="auth-first-name" autocomplete="given-name" placeholder="Tus nombres"></label><label>Apellidos<input class="form-input" id="auth-last-name" autocomplete="family-name" placeholder="Tus apellidos"></label>${schoolFields}${roleFields}`:""}<label>Correo electrónico<input class="form-input" id="auth-email" type="email" autocomplete="email" value="${escapeHtml(state.authPendingEmail||'')}" placeholder="nombre@correo.com"></label><label>Contraseña<input class="form-input" id="auth-password" type="password" autocomplete="${creating?"new-password":"current-password"}" placeholder="${creating?"Mínimo 8 caracteres":"Tu contraseña"}"></label>${creating?`<label>Confirma la contraseña<input class="form-input" id="auth-confirm" type="password" autocomplete="new-password" placeholder="Repite tu contraseña"></label>`:""}</div><p class="auth-message" id="auth-message" role="alert" ${state.authMessage?"":"hidden"}>${escapeHtml(state.authMessage)}</p><button class="wide-button" data-action="submit-auth">${creating?"Crear mi cuenta":"Iniciar sesión"}</button>${!creating?`<button class="auth-link" data-auth-mode="recover">Olvidé mi contraseña</button><button class="auth-link" data-action="resend-confirmation">Reenviar correo de verificación</button>`:''}<p class="auth-note">${window.aulayaDb?.isConfigured()?"Tu cuenta y progreso se guardan en la nube.":"La sincronización en la nube estará disponible al conectar la base de datos."}</p></div></div>`);if(creating){loadSchoolDepartments();if(state.schoolDepartment&&!state.schoolMunicipalities.length)loadSchoolMunicipalities(state.schoolDepartment);if(state.schoolMunicipality&&!state.schoolResults.length){loadSchoolAreas();loadSchools()}}}
function showAuthMessage(message){state.authMessage=message;const node=document.querySelector('#auth-message');if(node){node.textContent=message;node.hidden=!message}else render()}

async function submitCloudAuth(){
  const creating=state.authMode==='create',teacher=state.authRole==='teacher';
  const firstName=document.querySelector('#auth-first-name')?.value.trim()||'',lastName=document.querySelector('#auth-last-name')?.value.trim()||'',name=[firstName,lastName].filter(Boolean).join(' '),email=document.querySelector('#auth-email')?.value.trim().toLowerCase()||'',password=document.querySelector('#auth-password')?.value||'',grade=document.querySelector('#auth-grade')?.value||'',school=state.schoolSelected?{...state.schoolSelected,department:state.schoolDepartment,municipality:state.schoolMunicipality,area:state.schoolArea}:null;
  const courses=document.querySelector('#all-primary')?.checked?['Toda primaria']:[...document.querySelectorAll('input[name="teacher-course"]:checked')].map(input=>input.value),subjects=[...document.querySelectorAll('input[name="teacher-subject"]:checked')].map(input=>input.value),variedSubjects=!!document.querySelector('#varied-subjects')?.checked;
  if(creating&&school&&!(school.name&&school.department&&school.municipality&&school.area)){showAuthMessage('Selecciona departamento, municipio, zona e institución educativa.');return}
  if(!email||!password||creating&&(!firstName||!lastName||!school)){showAuthMessage('Completa tus datos y selecciona la institución educativa.');return}
  if(creating&&!teacher&&!grade){showAuthMessage('Selecciona tu curso o grado.');return}
  if(creating&&teacher&&!courses.length){showAuthMessage('Selecciona los grados que dictas o marca toda primaria.');return}
  if(creating&&teacher&&!subjects.length&&!variedSubjects){showAuthMessage('Selecciona las materias que dictas o marca materias variadas.');return}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)){showAuthMessage('Escribe un correo electrónico válido.');return}
  if(creating&&password.length<8){showAuthMessage('La contraseña debe tener al menos 8 caracteres.');return}
  if(creating&&password!==document.querySelector('#auth-confirm')?.value){showAuthMessage('Las contraseñas no coinciden.');return}
  try{
    state.authMessage='';
    const metadata={role:teacher?'teacher':'student',name,first_name:firstName,last_name:lastName,grade:teacher?null:grade,institution:school,courses:teacher?courses:[],subjects:teacher?subjects:[],varied_subjects:teacher&&variedSubjects};
    const result=await window.aulayaDb.authenticate(creating?'signup':'login',email,password,metadata),user=result?.user;
    if(creating&&!result?.access_token){state.authPendingEmail=email;state.authMode='login';state.authMessage='Si el correo está disponible para registrarse, enviaremos un enlace de confirmación. Revisa tu bandeja y spam. Si ya tienes cuenta, inicia sesión.';render();return}
    const loaded=creating?{user,profile:null}:await window.aulayaDb.loadProfile(),remoteUser=loaded?.user||user,profile=loaded?.profile,details=profile||remoteUser?.user_metadata||metadata;
    if(!remoteUser?.id)throw new Error('Supabase no devolvió los datos de la cuenta.');
    const registeredRole=remoteUser?.user_metadata?.role||profile?.role||metadata.role,wantedRole=teacher?'teacher':'student';
    if(registeredRole&&registeredRole!==wantedRole){await window.aulayaDb.signOut().catch(()=>{});showAuthMessage(registeredRole==='teacher'?'Este correo está registrado como docente. Vuelve atrás y entra por "Docente".':'Este correo está registrado como estudiante. Vuelve atrás y entra por "Estudiante".');return}
    if(state.cloudUserId!==remoteUser.id)clearAccountState();state.cloudUserId=remoteUser.id;
    const role=registeredRole||'student',savedName=details.name||name||email.split('@')[0],savedFirst=details.first_name||savedName.split(/\s+/)[0],savedLast=details.last_name||savedName.split(/\s+/).slice(1).join(' '),savedSchool=details.institution||school;
    state.authRole=role;state.authEmail=email;state.email=email;state.profile=savedName;state.firstName=savedFirst;state.lastName=savedLast;state.school=savedSchool;state.authIntroSeen=true;
    const savedState=profile?.app_state&&typeof profile.app_state==='object'&&Object.keys(profile.app_state).length?profile.app_state:null;
    let usableState=savedState;try{const q=JSON.parse(localStorage.getItem(CLOUD_OUTBOX_KEY)||'{}'),queued=q[remoteUser.id];if(queued){const serverTime=Date.parse(profile?.updated_at||0)||0;if(queued.revision>serverTime&&queued.profile?.app_state&&queued.profile.role===role)usableState=queued.profile.app_state;else{delete q[remoteUser.id];localStorage.setItem(CLOUD_OUTBOX_KEY,JSON.stringify(q))}}}catch(_){}
    if(usableState){const {email:_e,authEmail:_a,authRole:_r,modal:_m,profiles:_p,profileData:_d,...rest}=usableState;Object.assign(state,rest)}state.authRole=role;state.authEmail=email;state.email=email;if(role==='student'&&details.grade)state.grade=details.grade;
    if(creating||!savedState||!Array.isArray(savedState.notifications)){state.notifications=[];addWelcomeNotification(role)}
    if(role==='teacher'){state.teacherCourses=details.courses||[];state.teacherSubjects=details.subjects||[];state.variedSubjects=!!details.varied_subjects;if(!savedState){state.teacherClasses=[];state.teacherActivities=[];state.teacherAvatar=0}else{state.teacherClasses=state.teacherClasses||[];state.teacherActivities=state.teacherActivities||[]}state.teacherView='home';state.page='teacher-blank'}
    else{if(creating||!savedState)resetStudentAccount(savedName,email,savedSchool);state.profile=savedName;state.firstName=savedFirst;state.lastName=savedLast;state.grade=details.grade||grade||state.grade;state.authRole='student';state.page='home'}
    rememberDeviceAccount({id:remoteUser.id,email,name:savedName,role});await window.aulayaDb.saveProfile(cloudProfilePayload());render();if(role==='teacher'){refreshTeacherNotifications();refreshClassProgress(true)}if(role==='student'){flushSupportAlerts();refreshStudentActivities()}toastMsg(creating?'Cuenta creada y sincronizada.':'¡Hola, '+savedFirst+'!');
  }catch(error){
    const message=String(error?.message||'');
    if(/already registered|user already exists/i.test(message))showAuthMessage('Ese correo ya está registrado. Un correo solo puede ser de docente o de estudiante: inicia sesión por el tipo de cuenta con el que lo registraste.');
    else if(/invalid login credentials/i.test(message))showAuthMessage('Correo o contraseña incorrectos.');
    else if(/email not confirmed/i.test(message)){state.authPendingEmail=email;showAuthMessage('Confirma tu correo desde el enlace que te enviamos. También puedes reenviar el correo de verificación.');}
    else if(/email_address_not_authorized/i.test(message))showAuthMessage('Supabase aún no puede enviar correos a esta dirección. Configura un servidor SMTP en Authentication para habilitar correos a todos los usuarios.');
    else if(/over_email_send_rate_limit|email rate limit exceeded/i.test(message))showAuthMessage('Se alcanzó el límite de envío de correos. Espera un momento o configura un servidor SMTP propio.');
    else showAuthMessage(message||'No se pudo conectar. Revisa tu conexión e inténtalo de nuevo.');
  }
}

async function sendPasswordReset(){const email=document.querySelector('#auth-email')?.value.trim().toLowerCase()||'';if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)){showAuthMessage('Escribe el correo asociado a tu cuenta.');return}try{await window.aulayaDb.requestPasswordReset(email);state.authMessage='Si existe una cuenta con ese correo, recibirás un enlace para recuperar el acceso.';render()}catch(error){showAuthMessage(error.message||'No se pudo enviar el enlace. Revisa tu conexión e inténtalo de nuevo.')}}

