const DEVICE_ACCOUNTS_KEY='aulaya-device-accounts';
function deviceAccounts(){try{const l=JSON.parse(localStorage.getItem(DEVICE_ACCOUNTS_KEY)||'[]');return Array.isArray(l)?l:[]}catch(_){return []}}
