function sharedVideoMaterialsMarkup(){const grade=state.grade||'Primero',subject=state.subject||'Matemáticas',topic=state.topic,offline=(state.offlineVideos||[]).filter(item=>item.grade===grade&&item.subject===subject&&item.topic===topic),rows=[...(state.sharedClassMaterials||[]).filter(item=>item.grade===grade&&item.subject===subject&&item.topic===topic)];for(const m of studentActivityMaterials())if(m.subject===subject&&m.topic===topic&&!rows.some(r=>r.id===m.id))rows.push(m);for(const item of offline)if(!rows.some(row=>row.id===item.id))rows.push(item);if(!rows.length)return `<div class="teacher-mini-empty">${state.page==='teacher-activity'?'Esta actividad no tiene archivos adjuntos.':'Tu docente todavía no ha compartido archivos para descargar.'}</div>`;return rows.map(item=>{const saved=offline.some(video=>video.id===item.id),id=escapeHtml(item.id);return `<article class="shared-video-row"><div class="shared-video-copy"><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.description||'Archivo de la clase')} · ${saved?'Guardado en este dispositivo':'Archivo de tu docente'}</small></div><div class="shared-video-actions">${saved?`<button class="download-action done" data-play-offline-video="${id}">Abrir sin internet ▶</button>`:`<button class="download-action" data-download-class-video="${id}">Descargar</button>`}</div><div class="shared-video-player" id="offline-player-${id}"></div></article>`}).join('')}
async function loadTopicSharedMaterials(){const grade=state.grade||'Primero',subject=state.subject||'Matemáticas',topic=state.topic;if(!navigator.onLine||!window.aulayaDb?.isConfigured())return;try{const rows=await window.aulayaDb.loadClassMaterials(grade,subject,topic);if(!['topic','teacher-activity'].includes(state.page)||state.topic!==topic||state.subject!==subject)return;state.sharedClassMaterials=rows||[];const list=document.querySelector('#shared-video-list');if(list)list.innerHTML=sharedVideoMaterialsMarkup()}catch(error){console.warn('No se pudieron cargar los videos de la clase:',error)}}
async function downloadSharedClassVideo(id){const item=(state.sharedClassMaterials||[]).find(video=>video.id===id)||studentActivityMaterials().find(m=>m.id===id);if(!item){toastMsg('Este video ya no aparece en la lista. Conéctate e inténtalo de nuevo.');return}const button=document.querySelector(`[data-download-class-video="${CSS.escape(id)}"]`);if(button){button.disabled=true;button.textContent='Descargando…'}try{const blob=await window.aulayaDb.downloadClassVideo(item.file_path);await storeOfflineVideo(item.id,blob);state.offlineVideos??=[];state.offlineVideos=state.offlineVideos.filter(video=>video.id!==item.id);state.offlineVideos.push({id:item.id,file_path:item.file_path,title:item.title,description:item.description,grade:item.grade,subject:item.subject,topic:item.topic,mime_type:item.mime_type,file_size:item.file_size});saveState();const list=document.querySelector('#shared-video-list');if(list)list.innerHTML=sharedVideoMaterialsMarkup();if(state.page==='downloads')render();toastMsg('Archivo guardado en este dispositivo para usarlo sin internet.')}catch(error){if(button){button.disabled=false;button.textContent='Descargar'}toastMsg(error.message||'No se pudo guardar el archivo en este dispositivo.')}}
