function downloadSuccess(){let name=state.successName||'Guía de ejercicios';shell(`<div class="success-card"><div class="success-icon">✓</div><h2>¡Listo!</h2><p>Material descargado</p><div class="download-row" style="text-align:left"><span class="file-icon pdf">PDF</span><span class="file-copy"><b>${name}</b><small>Listo para usar sin internet</small></span><span class="download-action done">✓</span></div><button class="wide-button" data-action="view-downloaded">▣ &nbsp; Ver ahora (sin internet)</button><button class="wide-button secondary" data-go="topic">↶ &nbsp; Volver al tema</button></div>`)}
