function pendingRevision(){const uid=window.aulayaDb?.userId?.();if(!uid)return null;try{return JSON.parse(localStorage.getItem(CLOUD_OUTBOX_KEY)||'{}')[uid]?.revision||null}catch(_){return null}}
function hasPendingTeacherFiles(){return state.authRole==='teacher'&&(state.teacherClasses||[]).some(c=>(c.activities||[]).some(a=>a.pendingFile))}
async function flushPendingTeacherFiles(){if(!navigator.onLine||!window.aulayaDb?.isConfigured?.()||!window.aulayaDb.userId?.())return 0;let done=0;for(const c of (state.teacherClasses||[]))for(const a of (c.activities||[])){const pf=a.pendingFile;if(!pf)continue;try{const blob=await readOfflineVideo(pf.key);if(!blob){delete a.pendingFile;continue}const file=new File([blob],pf.name,{type:pf.type});await window.aulayaDb.saveProfile(cloudProfilePayload());const id=window.crypto?.randomUUID?window.crypto.randomUUID():`video-${Date.now().toString(36)}`,path=`${window.aulayaDb.userId()}/${c.id}/${id}.${fileExtension(pf.name)}`;await window.aulayaDb.uploadClassVideo(path,file);let material=null;try{material=await window.aulayaDb.createClassMaterial({teacher_id:window.aulayaDb.userId(),teacher_class_id:c.id,title:a.title,description:a.description||'',grade:a.grade,subject:a.subject,topic:a.topic,file_path:path,mime_type:pf.type,file_size:pf.size})}catch(e){await window.aulayaDb.deleteClassVideo(path);throw e}a.videoMaterial=material;delete a.pendingFile;await removeOfflineVideo(pf.key).catch(()=>{});done++}catch(error){console.warn('El material pendiente se volverá a intentar:',error)}}if(done){saveState();if(state.page==='teacher-blank')render()}return done}
function hasPendingUpload(){const uid=window.aulayaDb?.userId?.();if(!uid)return false;try{return !!JSON.parse(localStorage.getItem(CLOUD_OUTBOX_KEY)||'{}')[uid]}catch(_){return false}}
function showSyncPop(title,text,icon='assets/aulaya-mascot.png'){document.querySelector('.sync-pop')?.remove();const el=document.createElement('div');el.className='sync-pop';el.setAttribute('role','status');el.innerHTML=`<img src="${icon}" alt=""><div><b>${escapeHtml(title)}</b><small>${escapeHtml(text)}</small></div><button aria-label="Cerrar">✕</button>`;document.body.appendChild(el);requestAnimationFrame(()=>el.classList.add('show'));const close=()=>{el.classList.remove('show');setTimeout(()=>el.remove(),350)};el.querySelector('button').onclick=close;setTimeout(close,7000)}
let syncRunning=false;
async function syncAfterReconnect(announce=false){if(syncRunning||!navigator.onLine||!window.aulayaDb?.isConfigured?.()||!window.aulayaDb.userId?.())return;syncRunning=true;try{await syncAfterReconnectInner(announce)}finally{syncRunning=false}}
async function syncAfterReconnectInner(announce){const role=state.authRole,pendingRev=pendingRevision(),hadPending=!!pendingRev,before=new Set((state.studentActivities||[]).map(a=>a.id));const files=role==='teacher'?await flushPendingTeacherFiles():0;await flushCloudOutbox();const uploaded=hadPending&&pendingRevision()!==pendingRev;flushSupportAlerts();if(role==='student')await refreshStudentActivities();else if(role==='teacher'){if(typeof refreshTeacherNotifications==='function')refreshTeacherNotifications();refreshClassProgress(true);flushBankQuestions()}const fresh=role==='student'?studentActivities().filter(a=>!before.has(a.id)).length:0;if(files)showSyncPop(files===1?'¡Listo! Tu material ya se subió 📎':`¡Listo! Se subieron ${files} materiales 📎`,'Tus estudiantes ya pueden verlo y descargarlo.');else if(!announce){}else if(uploaded&&role==='student')showSyncPop('¡Listo! Tu avance ya está guardado ⭐',fresh?`Tu profe ya puede ver lo que hiciste. ¡Y te dejó ${fresh} ${fresh===1?'actividad nueva':'actividades nuevas'}!`:'Tu profe ya puede ver todo lo que hiciste sin internet. ¡Muy bien!');else if(uploaded)showSyncPop('¡Listo! Tus cambios ya se subieron ☁️','Tus estudiantes ya pueden ver lo que preparaste sin internet.');else if(fresh)showSyncPop('¡Tienes actividades nuevas! 📌',`Tu profe te dejó ${fresh} ${fresh===1?'actividad nueva':'actividades nuevas'}.`);if(state.page==='home'||state.page==='downloads')render()}
let offlineTimer=null,wasOffline=false;
window.addEventListener('offline',()=>{clearTimeout(offlineTimer);offlineTimer=setTimeout(()=>{if(navigator.onLine)return;wasOffline=true;state.offline=true;showSyncPop('Estás sin internet 📴',state.authRole==='teacher'?'Puedes seguir trabajando. Tus cambios se guardan aquí y se suben cuando vuelva la conexión.':'¡Sigue aprendiendo! Todo lo que hagas se guarda aquí y se sube cuando vuelva el internet.');if(state.page==='home')render()},2500)});
function setupScrollHelper(){if(document.querySelector('.scroll-helper'))return;const box=document.createElement('div');box.className='scroll-helper';box.innerHTML='<button data-scroll="top" aria-label="Ir arriba del todo" title="Ir arriba del todo">⤒</button><button data-scroll="up" aria-label="Subir" title="Subir">▲</button><button data-scroll="down" aria-label="Bajar" title="Bajar">▼</button><button data-scroll="bottom" aria-label="Ir abajo del todo" title="Ir abajo del todo">⤓</button>';document.body.appendChild(box);box.addEventListener('click',e=>{const b=e.target.closest('[data-scroll]');if(!b)return;const sheet=document.querySelector('.modal-sheet'),el=sheet&&sheet.scrollHeight>sheet.clientHeight?sheet:document.scrollingElement,h=(sheet&&el===sheet?sheet.clientHeight:window.innerHeight)*0.7,dir=b.dataset.scroll;const top=dir==='top'?0:dir==='bottom'?el.scrollHeight:el.scrollTop+(dir==='down'?h:-h);el.scrollTo({top,behavior:'auto'})})}
setupScrollHelper();
function quickRefresh(){if(document.hidden||!navigator.onLine)return;if(hasPendingUpload()||hasPendingTeacherFiles()){syncAfterReconnect(false);return}if(state.authRole==='student')refreshStudentActivities();else if(state.authRole==='teacher'){if(typeof refreshTeacherNotifications==='function')refreshTeacherNotifications();refreshClassProgress()}}
setInterval(quickRefresh,10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)quickRefresh()});window.addEventListener('focus',quickRefresh);
