/* ===== Teo v2: motor por temas (teo-brain.js) + modelo opcional ===== */
function teoCtx(){state.teoMemory??={};const a=studentActivities().find(x=>x.id===state.openActivityId);return {grade:state.grade||'Primero',name:state.firstName||String(state.profile||'').split(/\s+/)[0]||'',memory:state.teoMemory,focusTopic:a?{subject:a.subject,topic:a.topic}:(state.subject&&state.topic?{subject:state.subject,topic:state.topic}:null)}}
function teoBubble(m,i,arr){const last=i===arr.length-1;if(m.role==='user')return `<div class="teo-msg user"><p>${escapeHtml(m.content)}</p></div>`;return `<div class="teo-msg teo ${m.kind||''}"><img class="teo-av" src="assets/aulaya-mascot.png" alt=""><div class="teo-bubble">${m.kind==='celebrate'?'<span class="teo-burst" aria-hidden="true">🎉</span>':''}<p>${escapeHtml(m.content).replace(/\n/g,'<br>')}</p>${last&&(state.aiChips||[]).length?`<div class="teo-chips">${state.aiChips.map(c=>`<button type="button" data-teo-chip="${escapeHtml(c)}">${escapeHtml(c)}</button>`).join('')}</div>`:''}</div></div>`}
function aiMessagesMarkup(){const msgs=state.aiMessages||[];if(!msgs.length){const sugg=window.TeoBrain?window.TeoBrain.suggestions(teoCtx()):[];state.aiChips=sugg;return teoBubble({role:'assistant',content:`¡Hola${teoCtx().name?' '+teoCtx().name:''}! 🐯 Soy Teo.\nPregúntame de tus temas, pídeme ejemplos o un ejercicio y yo reviso tu respuesta. ¡Aprendamos jugando!`},0,[1])}return msgs.map(teoBubble).join('')+(state.teoTyping?'<div class="teo-msg teo"><img class="teo-av" src="assets/aulaya-mascot.png" alt=""><div class="teo-bubble typing"><i></i><i></i><i></i></div></div>':'')}
function renderAiMessages(){const box=document.querySelector('#ai-messages');if(box){box.innerHTML=aiMessagesMarkup();box.scrollTop=box.scrollHeight}const sc=document.querySelector('.teo-score');if(sc)sc.textContent=`⭐ ${state.teoMemory?.correct||0}`}
function assistant(){const ctx=teoCtx(),topics=window.TeoBrain?window.TeoBrain.gradeTopics(ctx.grade):[];shell(`${heading('Teo','home',`<span class="teo-score" title="Retos resueltos con Teo">⭐ ${state.teoMemory?.correct||0}</span>`)}<section class="teo-hero"><img src="assets/aulaya-mascot.png" alt=""><div><b>Tu compañero de estudio</b><small>Funciona sin internet · Solo temas de ${escapeHtml(ctx.grade)}</small></div></section><div class="teo-topics">${topics.map(t=>`<button type="button" data-teo-chip="Explícame ${escapeHtml(t.title.charAt(0).toLowerCase()+t.title.slice(1))}"><span>${subjectIcon(t.subject)}</span><b>${escapeHtml(t.title)}</b></button>`).join('')}</div><section class="ai-chat teo-chat" aria-label="Chat con Teo"><div class="ai-messages" id="ai-messages">${aiMessagesMarkup()}</div><form class="ai-compose" id="ai-chat-form"><input id="ai-chat-input" type="text" maxlength="300" placeholder="Escribe tu pregunta o tu respuesta…" autocomplete="off" aria-label="Escribe tu pregunta"><button type="submit" aria-label="Enviar mensaje">➤</button></form><div class="teo-tools"><button type="button" data-action="ai-clear">🧹 Nueva conversación</button></div></section><details class="teo-plus"><summary>✨ Teo Plus (opcional) · respuestas más largas</summary><section class="ai-model-panel" id="ai-model-panel"><div class="ai-model-copy"><b>Modelo de IA en este dispositivo</b><p>Teo ya funciona sin descargar nada. Si quieres explicaciones más largas, descarga una vez el modelo (necesita internet y un navegador con WebGPU).</p><small>Puede ocupar varios cientos de MB. Recomendado usar Wi-Fi.</small></div><button class="wide-button" data-action="ai-load">Preparar modelo</button><div class="ai-progress" hidden><span></span></div><small class="ai-model-status" aria-live="polite">Opcional.</small></section></details>`);const box=document.querySelector('#ai-messages');if(box)box.scrollTop=box.scrollHeight;if(window.teoOfflineAI?.ready)aiPanel('ready','Teo Plus está activo.',100);else if(localStorage.getItem('teo-model-cache-v2')==='ready'){prepareTeoModel()}}
function aiPanel(status,message='',progress=0){const panel=document.querySelector('#ai-model-panel');if(!panel)return;const button=panel.querySelector('[data-action="ai-load"]'),bar=panel.querySelector('.ai-progress'),fill=panel.querySelector('.ai-progress span'),label=panel.querySelector('.ai-model-status');if(label)label.textContent=message||'Opcional.';if(bar)bar.hidden=status!=='loading';if(fill)fill.style.width=`${Math.max(0,Math.min(100,progress))}%`;if(button){button.disabled=status==='loading'||status==='ready';button.textContent=status==='loading'?`Preparando · ${Math.round(progress)}%`:status==='ready'?'Teo Plus activo ✓':status==='error'?'Intentar de nuevo':'Preparar modelo'}}
async function sendTeoMessage(question){question=String(question||'').trim();if(!question||state.teoTyping)return;state.aiMessages??=[];state.aiChips=[];state.aiMessages.push({role:'user',content:question});const input=document.querySelector('#ai-chat-input');if(input)input.value='';state.teoTyping=true;renderAiMessages();const ctx=teoCtx();let res=window.TeoBrain?window.TeoBrain.reply(question,ctx):{text:'Estoy despertando… intenta de nuevo en un momento.'};let text=res.text;await new Promise(r=>setTimeout(r,450+Math.min(700,text.length*4)));if(res.llm&&window.teoOfflineAI?.ready){try{const extra=await window.teoOfflineAI.reply([{role:'system',content:window.TeoBrain.systemPrompt(ctx,res.context)},{role:'user',content:question}]);if(extra&&extra.length>20)text=`${text}\n\n${extra}`}catch(_){}}state.teoTyping=false;state.aiMessages.push({role:'assistant',content:text,kind:res.kind||''});state.aiChips=res.chips||[];if(res.kind==='celebrate'){state.coins=(state.coins||0)+1;teoConfetti()}if(state.aiMessages.length>60)state.aiMessages=state.aiMessages.slice(-60);saveState();renderAiMessages();if(res.kind==='celebrate')toastMsg('+1 moneda por tu respuesta 🪙');document.querySelector('#ai-chat-input')?.focus()}
function teoConfetti(){const host=document.body,colors=['#21a65d','#ffb51b','#4aa8f0','#f06292','#8e6cf0'];const wrap=document.createElement('div');wrap.className='confetti';for(let i=0;i<36;i++){const p=document.createElement('i');p.style.left=Math.random()*100+'%';p.style.background=colors[i%colors.length];p.style.animationDelay=(Math.random()*0.25)+'s';p.style.transform=`rotate(${Math.random()*360}deg)`;wrap.appendChild(p)}host.appendChild(wrap);setTimeout(()=>wrap.remove(),1800)}
app.addEventListener('click',e=>{const chip=e.target.closest('[data-teo-chip]');if(chip){e.stopPropagation();sendTeoMessage(chip.dataset.teoChip)}},true);
app.addEventListener('click',e=>{if(e.target.closest('[data-action="ai-clear"]')){state.teoMemory={};state.aiChips=[];}},true);

/* ===== Preguntas v2: directo, más visual y con celebraciones ===== */
function quizPraise(){const n=state.firstName?` ${String(state.firstName).split(/\s+/)[0]}`:'';return [`¡Excelente${n}! 🎉`,`¡Muy bien${n}! ⭐`,'¡Eso es! 🙌','¡Lo lograste! 🌟','¡Súper respuesta! 💪','¡Bravo! 👏','¡Eres un crack! 🚀','¡Perfecto! 🏆'][Math.floor(Math.random()*8)]}
function quizCheer(){return ['¡Casi! No pasa nada 💛','¡Uy, por poquito! 💪','¡Sigue intentando! 🌱','Así también se aprende 🔎'][Math.floor(Math.random()*4)]}
function quiz(){const questions=activeQuestionSet(),mode=state.quizMode||'main',review=mode==='review',done=mode==='done',order=review?(state.quizQuestionOrder||[]):questions.map((_,i)=>i),total=review?order.length:questions.length,qi=order[state.quiz]??0,q=questions[qi]||questions[0],fb=state.quizFeedback,back=state.quizSource==='teacher'?'teacher-activity':'topic',title=String(state.activeActivity||'Preguntas').replace(/^Docente:\s*/,'');
 if(done){const t=questions.length,miss=Number(state.quizInitialMissedCount)||0,pct=t?Math.round((t-miss)/t*100):100,stars=pct>=90?3:pct>=70?2:pct>0?1:0,msg=pct===100?['¡Perfecto! 🏆','Respondiste todo bien a la primera. ¡Eres una estrella!']:pct>=80?['¡Excelente trabajo! 🌟','Casi todo bien a la primera. ¡Sigue así!']:pct>=60?['¡Muy bien! 💪','Vas por buen camino. Repasa un poquito y serás imparable.']:['¡Buen esfuerzo! 💛','Repasaste las difíciles. Practica con Teo y verás cómo mejoras.'];
  if(!state.quizDoneCelebrated){state.quizDoneCelebrated=true;setTimeout(()=>window.teoConfetti&&teoConfetti(),150)}
  shell(`${heading(escapeHtml(title),back)}<section class="qz-done"><img class="qz-done-mascot" src="assets/aulaya-mascot.png" alt=""><div class="qz-stars">${[0,1,2].map(i=>`<span class="${i<stars?'on':''}" style="animation-delay:${i*0.18}s">★</span>`).join('')}</div><h2>${msg[0]}</h2><p>${msg[1]}</p><div class="qz-result"><div><b>${pct}%</b><small>a la primera</small></div><div><b>${t-miss}/${t}</b><small>sin ayuda</small></div><div><b>${state.quizIsRepeat?'—':'+'+(t*10)}</b><small>${state.quizIsRepeat?'repaso':'monedas'}</small></div></div><button class="qz-next" data-action="finish-quiz">${state.quizSource==='teacher'?'Volver a la tarea':'Volver al tema'} →</button><button class="qz-alt" data-go="assistant">🐯 Practicar más con Teo</button></section>`);return}
 state.quizDoneCelebrated=false;
 const dots=(review?order:questions.map((_,i)=>i)).map((idx,i)=>{const cur=i===state.quiz,ok=(state.quizCorrectIds||[]).includes(idx),missed=(state.quizMissed||[]).includes(idx)||(!review&&state.quizHintByQuestion?.[idx]);return `<i class="${cur?'cur':''} ${i<state.quiz||(cur&&fb)?(ok&&!missed?'ok':ok?'mid':'bad'):''}"></i>`}).join('');
 const say=fb?(fb.type==='correct'?fb.praise||'¡Muy bien!':fb.cheer||'¡Casi!'):review?'¡Segunda oportunidad! Tú puedes 💪':['¡Tú puedes! 💪','Lee con calma 👀','¡Piensa y elige! 🤔','¡Vamos por otra! 🚀'][state.quiz%4];
 if(fb&&fb.type==='correct'&&!fb.celebrated){fb.celebrated=true;setTimeout(()=>window.teoConfetti&&teoConfetti(),60)}
 const L='ABCD',opts=q.answers.map((a,i)=>{const st=fb?.type==='wrong'&&Number(fb.chosen)===i?'wrong':fb?.type==='correct'&&i===q.correct?'correct':'';return `<button class="qz-opt c${i} ${st}" data-answer="${i}" ${fb?'disabled':''}><span class="qz-letter">${st==='correct'?'✓':st==='wrong'?'✕':L[i]}</span><span class="qz-text">${escapeHtml(a)}</span></button>`}).join('');
 const streak=fb?.type==='correct'&&(state.quizStreak||0)>=2?`<span class="qz-streak">🔥 ${state.quizStreak} seguidas</span>`:'';
 const panel=fb?`<div class="qz-fb ${fb.type==='correct'?'good':'try'}"><div class="qz-fb-head"><b>${fb.type==='correct'?escapeHtml(fb.praise||'¡Muy bien!'):'💡 Pista para pensar'}</b>${streak}${fb.type==='correct'&&!state.quizIsRepeat?'<span class="qz-plus">🪙 +10</span>':''}</div><p>${escapeHtml(fb.text)}</p><button class="qz-next" data-action="${fb.type==='wrong'&&review?'retry-question':'next-question'}">${fb.type==='wrong'&&review?'Intentar de nuevo':fb.type==='wrong'?'Continuar':state.quiz+1>=total?'¡Terminar! 🎉':'Siguiente pregunta →'}</button></div>`:'';
 shell(`${heading(escapeHtml(title),back,`<span class="qz-count">${state.quiz+1}/${total}</span>`)}<section class="qz"><div class="qz-dots">${dots}</div><div class="qz-card ${fb?fb.type:''}"><div class="qz-mascot"><img src="assets/aulaya-mascot.png" alt=""><span class="qz-say">${escapeHtml(say)}</span></div><small class="qz-meta">${review?'Repaso':'Pregunta'} ${state.quiz+1} de ${total} · ${escapeHtml(state.topic||'')}</small><h2 class="qz-q">${escapeHtml(q.question)}</h2></div><div class="qz-opts">${opts}</div>${panel}</section>`);if(fb)setTimeout(()=>document.querySelector('.qz-fb')?.scrollIntoView({behavior:'smooth',block:'nearest'}),80)}

/* Preguntas: se responde directo desde la actividad */
app.addEventListener('click',e=>{const b=e.target.closest('[data-inline-answer]');if(!b)return;e.stopPropagation();const i=b.dataset.inlineAnswer,start=b.closest('.qz-inline')?.querySelector('.qzi-start');if(!start)return;start.click();setTimeout(()=>{if(state.page==='quiz')document.querySelector(`.qz-opt[data-answer="${i}"]`)?.click()},0)},true);
